(() => {
  "use strict";
  const SEED = window.STRENGTH_OS_SEED;
  const KEY = "strengthOSV2";
  const LEGACY_KEY = "strengthProteinTrackerV1";
  const MIGRATION_BACKUP_KEY = "strengthOSMigrationBackupV1";
  const VERSION = 2;
  const trackingTypes = [
    ["weight_reps","Weight + reps"],["bodyweight_reps","Bodyweight + reps"],["bodyweight_added","Bodyweight + added weight"],
    ["assisted_bodyweight","Assisted bodyweight"],["duration","Duration"],["weight_duration","Weight + duration"],
    ["reps_only","Reps only"],["distance_duration","Distance + duration"]
  ];
  const equipments = ["Barbell","Dumbbell","Cable","Machine","Bodyweight","Smith Machine","EZ Bar","Kettlebell","Plate","Bands","Other"];
  const setTypes = [["warmup","W"],["normal","N"],["drop","D"],["failure","F"],["amrap","A"]];
  const bodyFields = [
    ["weight","Weight","kg"],["waist","Waist","cm"],["chest","Chest","cm"],["armLeft","Left arm","cm"],["armRight","Right arm","cm"],
    ["thighLeft","Left thigh","cm"],["thighRight","Right thigh","cm"],["calfLeft","Left calf","cm"],["calfRight","Right calf","cm"],["hips","Hips","cm"]
  ];
  const byId = id => document.getElementById(id);
  const view = byId("view"), toast = byId("toast"), modal = byId("modal"), modalForm = byId("modalForm"), modalBody = byId("modalBody"), modalActions = byId("modalActions");
  let state = loadState();
  let activeView = "train";
  let progressTab = "overview";
  let historyMonth = startOfMonth(isoToday());
  let historyExerciseFilter = "all", historyMuscleFilter = "all", historyProgramFilter = "all";
  let librarySearch = "";
  let libraryMuscle = "all";
  let selectedProgramId = state.settings.activeProgramId;
  let selectedExerciseAnalyticsId = "bench";
  let trainPreviewProgramId = null, trainPreviewDayId = null;
  let restInterval = null, restEndAt = 0;
  let elapsedInterval = null;
  let deferredInstallPrompt = null;

  init();

  function init(){
    byId("todayLabel").textContent = new Date().toLocaleDateString(undefined,{weekday:"long",month:"short",day:"numeric"});
    document.querySelectorAll(".nav-btn").forEach(b=>b.addEventListener("click",()=>navigate(b.dataset.view)));
    byId("cancelTimer").addEventListener("click",stopRestTimer);
    byId("quickWeightBtn").addEventListener("click",()=>openBodyEntryModal(isoToday(),"weight"));
    window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();deferredInstallPrompt=e;byId("installBtn").classList.remove("hidden");});
    byId("installBtn").addEventListener("click",async()=>{if(!deferredInstallPrompt)return;deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;byId("installBtn").classList.add("hidden");});
    if("serviceWorker" in navigator) navigator.serviceWorker.register("./sw.js").catch(()=>{});
    render();
  }

  function newState(){
    const exerciseMap = Object.fromEntries(SEED.exercises.map(e=>[e.id,clone(e)]));
    const p = clone(SEED.program);
    return {
      version:VERSION,
      meta:{createdAt:Date.now(),updatedAt:Date.now(),migratedFrom:null},
      settings:{
        units:"kg",weekStarts:"monday",trackRir:true,autoRest:true,secondaryMultiplier:.5,
        activeProgramId:p.id,visibleBodyFields:["weight","waist"],plateInventory:[20,15,10,5,2.5,1.25],barWeight:20,
        muscleTargets:clone(SEED.targetRanges)
      },
      exercises:exerciseMap,
      programs:{[p.id]:p},
      sessions:[],bodyEntries:[],goals:[],currentWorkoutId:null
    };
  }

  function loadState(){
    try{
      const raw=localStorage.getItem(KEY);
      if(raw){const s=JSON.parse(raw);return normalizeState(s);}
      const legacy=localStorage.getItem(LEGACY_KEY);
      if(legacy){
        localStorage.setItem(MIGRATION_BACKUP_KEY,legacy);
        const migrated=migrateLegacy(JSON.parse(legacy));
        localStorage.setItem(KEY,JSON.stringify(migrated));
        return migrated;
      }
    }catch(e){console.warn("State load failed",e);}
    const s=newState();localStorage.setItem(KEY,JSON.stringify(s));return s;
  }

  function normalizeState(s){
    const base=newState();
    return {
      ...base,...s,version:VERSION,
      meta:{...base.meta,...(s.meta||{})},
      settings:{...base.settings,...(s.settings||{}),muscleTargets:{...base.settings.muscleTargets,...(s.settings?.muscleTargets||{})}},
      exercises:{...base.exercises,...(s.exercises||{})},programs:s.programs&&Object.keys(s.programs).length?s.programs:base.programs,
      sessions:Array.isArray(s.sessions)?s.sessions:[],bodyEntries:Array.isArray(s.bodyEntries)?s.bodyEntries:[],goals:Array.isArray(s.goals)?s.goals:[]
    };
  }

  function migrateLegacy(old){
    const s=newState();s.meta.migratedFrom="strengthProteinTrackerV1";s.meta.migratedAt=Date.now();
    Object.entries(old.body||{}).forEach(([date,v])=>{
      const entry={id:uid("body"),date}; if(num(v.weight)>0)entry.weight=num(v.weight);if(num(v.waist)>0)entry.waist=num(v.waist);s.bodyEntries.push(entry);
    });
    Object.entries(old.workouts||{}).forEach(([date,w])=>{
      const dayId=SEED.legacyProgramDayMap[w.programKey]||null;
      const pday=SEED.program.days.find(d=>d.id===dayId);
      const session={id:uid("sess"),date,programId:SEED.program.id,programDayId:dayId,name:pday?.name||"Migrated workout",status:w.status||"complete",startTime:null,endTime:w.completedAt||null,notes:"Migrated from Strength + Protein Tracker",items:[]};
      Object.entries(w.exercises||{}).forEach(([oldId,x])=>{
        const exId=SEED.legacyExerciseMap[oldId]||oldId;const ex=s.exercises[exId];if(!ex)return;
        session.items.push({id:uid("item"),exerciseId:exId,exerciseSnapshot:snapshotExercise(ex),substitutedForExerciseId:null,supersetGroup:"",notes:"",techniqueGood:x.techniqueGood!==false,pain:x.pain||"none",sets:(x.sets||[]).map(st=>({id:uid("set"),type:st.warmup?"warmup":"normal",loadKg:num(st.load)||0,reps:num(st.reps)||0,rir:st.rir===""||st.rir==null?null:num(st.rir),durationSec:0,distanceKm:0,complete:num(st.reps)>0}))});
      });
      if(session.items.length)s.sessions.push(session);
    });
    s.sessions.sort((a,b)=>a.date.localeCompare(b.date));return s;
  }

  function save(){state.meta.updatedAt=Date.now();localStorage.setItem(KEY,JSON.stringify(state));}
  function clone(o){return JSON.parse(JSON.stringify(o));}
  function uid(prefix="id"){return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`;}
  function num(v){const n=Number(v);return Number.isFinite(n)?n:0;}
  function clamp(v,min,max){const n=Number(v);return Number.isFinite(n)?Math.max(min,Math.min(max,n)):null;}
  function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));}
  function cap(s){return s?String(s).charAt(0).toUpperCase()+String(s).slice(1):"";}
  function isoToday(){const d=new Date();return isoFromDate(d);}
  function isoFromDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;}
  function dateObj(s){const [y,m,d]=s.split("-").map(Number);return new Date(y,m-1,d,12);}
  function addDays(s,n){const d=dateObj(s);d.setDate(d.getDate()+n);return isoFromDate(d);}
  function fmtDate(s,opts={weekday:"short",month:"short",day:"numeric"}){return dateObj(s).toLocaleDateString(undefined,opts);}
  function fmtDateTime(ms){return ms?new Date(ms).toLocaleString(undefined,{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}):"—";}
  function startOfMonth(s){const d=dateObj(s);d.setDate(1);return isoFromDate(d);}
  function startOfWeek(s){const d=dateObj(s),day=d.getDay();const mondayOffset=day===0?-6:1-day;const sundayOffset=-day;d.setDate(d.getDate()+(state?.settings?.weekStarts==="sunday"?sundayOffset:mondayOffset));return isoFromDate(d);}
  function durationText(sec){sec=Math.max(0,Math.floor(sec||0));const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;return h?`${h}h ${m}m`:`${m}:${String(s).padStart(2,"0")}`;}
  function restText(sec){const m=Math.floor(sec/60),s=sec%60;return `${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;}
  function round1(n){return Math.round(n*10)/10;}
  function unitWeight(kg){return state.settings.units==="lb"?round1(kg*2.2046226218):round1(kg);}
  function toKg(display){return state.settings.units==="lb"?num(display)/2.2046226218:num(display);}
  function weightUnit(){return state.settings.units;}
  function muscleName(id){return SEED.muscles.find(m=>m.id===id)?.name||id||"Unknown";}
  function trackingLabel(id){return trackingTypes.find(x=>x[0]===id)?.[1]||id;}
  function snapshotExercise(ex){return {name:ex.name,primaryMuscle:ex.primaryMuscle,secondaryMuscles:[...(ex.secondaryMuscles||[])],equipment:ex.equipment,trackingType:ex.trackingType};}
  function sessionDuration(s){if(!s.startTime)return 0;return Math.max(0,Math.floor(((s.endTime||Date.now())-s.startTime)/1000));}
  function activeProgram(){return state.programs[state.settings.activeProgramId]||Object.values(state.programs)[0]||null;}
  function todayProgramDay(){const p=activeProgram();if(!p)return null;const dow=dateObj(isoToday()).getDay();return p.days.find(d=>Number(d.weekday)===dow)||null;}
  function getSession(id){return state.sessions.find(s=>s.id===id)||null;}
  function getExercise(id){return state.exercises[id]||null;}
  function liveSession(){return state.currentWorkoutId?getSession(state.currentWorkoutId):null;}
  function workingSets(item){return (item.sets||[]).filter(s=>s.type!=="warmup"&&s.complete);}
  function allWorkingSets(item){return (item.sets||[]).filter(s=>s.type!=="warmup");}
  function previousExerciseSession(exerciseId,beforeDate,excludeSessionId=null){return state.sessions.filter(s=>s.id!==excludeSessionId&&s.date<=beforeDate&&["complete","shortened"].includes(s.status)&&s.items?.some(i=>i.exerciseId===exerciseId)).sort((a,b)=>(b.date+a.id).localeCompare(a.date+b.id))[0]||null;}
  function previousExerciseItem(exerciseId,beforeDate,excludeSessionId=null){const s=previousExerciseSession(exerciseId,beforeDate,excludeSessionId);return s?.items.find(i=>i.exerciseId===exerciseId)||null;}
  function e1rm(loadKg,reps){if(loadKg<=0||reps<=0||reps>20)return 0;return loadKg*(1+reps/30);}
  function setVolume(s){return s.complete&&s.type!=="warmup"?num(s.loadKg)*num(s.reps):0;}
  function isRepBased(ex){return ["weight_reps","bodyweight_reps","bodyweight_added","assisted_bodyweight","reps_only"].includes(ex.trackingType);}
  function isDurationBased(ex){return ["duration","weight_duration"].includes(ex.trackingType);}

  function navigate(v){if(v!=="train"){trainPreviewProgramId=null;trainPreviewDayId=null;} activeView=v;document.querySelectorAll(".nav-btn").forEach(b=>b.classList.toggle("active",b.dataset.view===v));stopElapsedTimer();render();}
  function render(){
    byId("todayLabel").textContent=new Date().toLocaleDateString(undefined,{weekday:"long",month:"short",day:"numeric"});
    if(activeView==="train")renderTrain(); else if(activeView==="programs")renderPrograms(); else if(activeView==="history")renderHistory(); else if(activeView==="progress")renderProgress(); else renderMore();
  }
  function showToast(msg){toast.textContent=msg;toast.classList.add("show");clearTimeout(showToast.t);showToast.t=setTimeout(()=>toast.classList.remove("show"),1900);}

  // ---------- TRAIN ----------
  function renderTrain(){const live=liveSession();if(live)return renderLiveSession(live);
    const p=activeProgram(),d=todayProgramDay();const latestWeight=latestBody("weight"),avg7=bodyAverage("weight",7);
    const week=weekSummary(isoToday());
    if(trainPreviewProgramId&&trainPreviewDayId){
      const pp=state.programs[trainPreviewProgramId]||p;
      const pd=pp?.days.find(x=>x.id===trainPreviewDayId);
      if(pd)return renderTrainPreview(pp,pd);
      trainPreviewProgramId=null;trainPreviewDayId=null;
    }
    view.innerHTML=`<div class="stack">
      <section class="card hero"><div class="row start"><div><p class="meta">Active program</p><h2>${esc(p?.name||"No active program")}</h2><p class="meta">${d?`Today · ${esc(d.name)}`:"No scheduled session today"}</p></div><span class="pill ${week.completed>=week.scheduled&&week.scheduled?"good":"neutral"}">${week.completed}/${week.scheduled} this week</span></div></section>
      ${d?`<section class="card"><div class="section-title"><h2>${esc(d.name)}</h2><span class="meta">${d.items.length} exercises · ${d.items.reduce((a,x)=>a+x.sets,0)} sets</span></div><div class="list" style="margin-top:7px">${d.items.slice(0,4).map(x=>`<div class="list-row"><div><strong>${esc(getExercise(x.exerciseId)?.name||"Missing exercise")}</strong><div class="meta">${x.sets} × ${x.min}–${x.max} · Priority ${x.priority}</div></div></div>`).join("")}${d.items.length>4?`<div class="meta">+ ${d.items.length-4} more exercises</div>`:""}</div><div class="preview-actions" style="margin-top:12px"><button class="btn primary" id="viewTodayBtn" type="button">View workout</button><button class="btn ghost" id="skipTodayBtn" type="button">Mark skipped</button></div></section>`:`<section class="card"><h2>Recovery / flexible day</h2><p class="muted">Start an empty workout or choose any program day if you want to train.</p></section>`}
      <section class="grid-2"><div class="metric"><span class="meta">Body weight</span><strong>${latestWeight?`${round1(latestWeight.weight)} kg`:"—"}</strong><span class="small muted">7-day avg ${avg7?`${round1(avg7)} kg`:"—"}</span></div><div class="metric"><span class="meta">Waist</span><strong>${latestBody("waist")?`${round1(latestBody("waist").waist)} cm`:"—"}</strong><span class="small muted">Latest measurement</span></div></section>
      <section class="card"><div class="section-title"><h2>Workout library</h2><button class="btn ghost small-btn" id="emptyWorkoutBtn" type="button">Empty workout</button></div><div class="list">${p?.days.map(day=>`<div class="list-row click-row preview-program-day" data-day="${day.id}"><div><strong>${esc(day.name)}</strong><div class="meta">${weekdayName(day.weekday)} · ${day.items.length} exercises</div></div><span>›</span></div>`).join("")||`<p class="empty">Create a program first.</p>`}</div></section>
    </div>`;
    byId("viewTodayBtn")?.addEventListener("click",()=>openTrainPreview(p.id,d.id));
    byId("skipTodayBtn")?.addEventListener("click",()=>markSkippedWorkout(p.id,d.id));
    byId("emptyWorkoutBtn")?.addEventListener("click",startEmptyWorkout);
    document.querySelectorAll(".preview-program-day").forEach(r=>r.addEventListener("click",()=>openTrainPreview(p.id,r.dataset.day)));
  }

  function openTrainPreview(programId,dayId){trainPreviewProgramId=programId;trainPreviewDayId=dayId;renderTrain();}

  function renderTrainPreview(programObj,day){
    const totalSets=day.items.reduce((a,x)=>a+x.sets,0);
    view.innerHTML=`<div class="stack"><section class="card"><div class="preview-head"><button class="btn ghost small-btn back-inline" id="backToTrainBtn" type="button">‹ Back</button><div class="preview-title"><p class="eyebrow">Workout preview</p><h2>${esc(day.name)}</h2><p class="meta">${esc(programObj?.name||"Program")} · ${day.items.length} exercises · ${totalSets} sets</p></div><span class="pill neutral">Preview</span></div><div class="preview-actions three"><button class="btn primary" id="startPreviewWorkoutBtn" type="button">Start workout</button><button class="btn ghost" id="previewSkipBtn" type="button">Mark skipped</button><button class="btn ghost" id="previewEmptyBtn" type="button">Empty workout</button></div></section><section class="card"><div class="section-title"><h2>Exercises</h2><span class="meta">Tap Start when you're ready</span></div><div class="list">${day.items.map((x,idx)=>{const ex=getExercise(x.exerciseId)||{name:"Missing exercise",primaryMuscle:""};return `<div class="exercise-preview-row"><div><strong>${idx+1}. ${esc(ex.name)}</strong><div class="meta">${x.sets} × ${x.min}–${x.max} · ${restText(x.rest)} rest · Priority ${x.priority}</div><div class="meta">${muscleName(ex.primaryMuscle)}${ex.equipment?` · ${esc(ex.equipment)}`:''}</div></div><span class="pill ${x.priority==='A'?'good':x.priority==='B'?'neutral':'warn'}">${x.priority}</span></div>`;}).join("")}</div></section></div>`;
    byId('backToTrainBtn').addEventListener('click',()=>{trainPreviewProgramId=null;trainPreviewDayId=null;renderTrain();});
    byId('startPreviewWorkoutBtn').addEventListener('click',()=>startProgramWorkout(programObj.id,day.id));
    byId('previewSkipBtn').addEventListener('click',()=>markSkippedWorkout(programObj.id,day.id));
    byId('previewEmptyBtn').addEventListener('click',startEmptyWorkout);
  }

  function weekdayName(n){return ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"][Number(n)]||"Unscheduled";}
  function startProgramWorkout(programId,dayId){
    if(state.currentWorkoutId){showToast("Finish or close the current workout first.");return;}
    const p=state.programs[programId],d=p?.days.find(x=>x.id===dayId);if(!d)return;
    const session={id:uid("sess"),date:isoToday(),programId,programDayId:dayId,name:d.name,status:"in_progress",startTime:Date.now(),endTime:null,notes:"",items:d.items.map(pi=>makeSessionItem(pi))};
    state.sessions.push(session);state.currentWorkoutId=session.id;save();renderTrain();showToast("Workout started.");
  }
  function markSkippedWorkout(programId,dayId){
    const p=state.programs[programId],d=p?.days.find(x=>x.id===dayId);if(!d)return;
    if(!confirm(`Mark ${d.name} as skipped for today?`))return;
    state.sessions.push({id:uid("sess"),date:isoToday(),programId,programDayId:dayId,name:d.name,status:"skipped",startTime:null,endTime:Date.now(),notes:"",items:[]});save();renderTrain();showToast("Workout marked skipped.");
  }
  function startEmptyWorkout(){
    const session={id:uid("sess"),date:isoToday(),programId:null,programDayId:null,name:"Empty Workout",status:"in_progress",startTime:Date.now(),endTime:null,notes:"",items:[]};state.sessions.push(session);state.currentWorkoutId=session.id;save();renderTrain();
  }
  function makeSessionItem(pi){const ex=getExercise(pi.exerciseId);return {id:uid("item"),exerciseId:pi.exerciseId,exerciseSnapshot:snapshotExercise(ex||{name:"Missing",primaryMuscle:"",secondaryMuscles:[],equipment:"",trackingType:"weight_reps"}),substitutedForExerciseId:null,supersetGroup:pi.supersetGroup||"",notes:pi.notes||"",techniqueGood:true,pain:"none",target:{sets:pi.sets,min:pi.min,max:pi.max,rest:pi.rest,priority:pi.priority,rirMin:pi.rirMin,rirMax:pi.rirMax},sets:Array.from({length:pi.sets},()=>newSet("normal"))};}
  function newSet(type="normal"){return {id:uid("set"),type,loadKg:0,reps:0,rir:null,durationSec:0,distanceKm:0,complete:false};}

  function renderLiveSession(s){
    const elapsed=sessionDuration(s);const completedSets=s.items.reduce((n,i)=>n+workingSets(i).length,0);const totalSets=s.items.reduce((n,i)=>n+allWorkingSets(i).length,0);
    view.innerHTML=`<div class="stack">
      <section class="workout-head"><div class="row start"><div><p class="meta">${s.endTime?"Editing history":"Live workout"}</p><h2 style="margin:2px 0 0">${esc(s.name)}</h2><p class="meta">${fmtDate(s.date)} · <span id="elapsedTimer" class="timer-big">${durationText(elapsed)}</span></p></div><span class="pill ${s.status==="complete"?"good":s.status==="shortened"?"warn":"neutral"}">${cap(s.status.replace("_"," "))}</span></div><div class="progress-track" style="margin-top:12px;background:rgba(255,255,255,.18)"><div class="progress-fill" style="width:${totalSets?Math.min(100,completedSets/totalSets*100):0}%;background:#60a5fa"></div></div><div class="meta" style="margin-top:6px">${completedSets}/${totalSets} working sets logged</div></section>
      ${s.items.length?s.items.map((item,idx)=>liveExerciseCard(s,item,idx)).join(""):`<section class="card"><div class="empty">No exercises yet.</div></section>`}
      <section class="card"><div class="wrap"><button class="btn secondary" id="addExerciseLive" type="button">+ Exercise</button><button class="btn ghost" id="sessionNoteBtn" type="button">Session note</button></div>${s.notes?`<div class="note-box" style="margin-top:10px">${esc(s.notes)}</div>`:""}</section>
      <section class="card"><div class="form-grid three"><button class="status-btn btn primary" data-finish="complete" type="button">Finish complete</button><button class="status-btn btn secondary" data-finish="shortened" type="button">Finish shortened</button><button class="btn ghost" id="closeWorkoutBtn" type="button">${s.endTime?"Close editor":"Save & close"}</button></div><button class="btn danger" id="deleteSessionBtn" type="button" style="margin-top:10px;width:100%">Delete workout</button></section>
    </div>`;
    startElapsedTimer(s);
    s.items.forEach((item,idx)=>wireLiveExercise(s,item,idx));
    byId("addExerciseLive").addEventListener("click",()=>openExercisePicker(exId=>{const ex=getExercise(exId);s.items.push({id:uid("item"),exerciseId:exId,exerciseSnapshot:snapshotExercise(ex),substitutedForExerciseId:null,supersetGroup:"",notes:"",techniqueGood:true,pain:"none",target:{sets:3,min:ex.defaultMin,max:ex.defaultMax,rest:ex.defaultRest,priority:"B",rirMin:1,rirMax:2},sets:Array.from({length:3},()=>newSet("normal"))});save();renderLiveSession(s);},"Add exercise"));
    byId("sessionNoteBtn").addEventListener("click",()=>openTextModal("Session note",s.notes||"",v=>{s.notes=v;save();renderLiveSession(s);}));
    document.querySelectorAll("[data-finish]").forEach(b=>b.addEventListener("click",()=>finishSession(s,b.dataset.finish)));
    byId("closeWorkoutBtn").addEventListener("click",()=>{if(!s.endTime){state.currentWorkoutId=null;save();}else state.currentWorkoutId=null;save();navigate("history");});
    byId("deleteSessionBtn").addEventListener("click",()=>{if(!confirm("Delete this workout permanently?"))return;state.sessions=state.sessions.filter(x=>x.id!==s.id);if(state.currentWorkoutId===s.id)state.currentWorkoutId=null;save();navigate("history");});
  }

  function liveExerciseCard(session,item,idx){const ex=getExercise(item.exerciseId)||item.exerciseSnapshot;const prev=previousExerciseItem(item.exerciseId,addDays(session.date,-1),session.id);const suggestion=suggestLoad(ex,item,prev);const sets=item.sets||[];const sup=item.supersetGroup?`<span class="pill">Superset ${esc(item.supersetGroup)}</span>`:"";
    return `<section class="card exercise-card"><div class="exercise-top"><div class="row start"><div><div class="wrap"><h3>${esc(ex.name)}</h3><span class="pill">${esc(item.target?.priority||"B")}</span>${sup}</div><div class="target">${item.target?.sets||sets.length} × ${item.target?.min||ex.defaultMin}–${item.target?.max||ex.defaultMax} · ${restText(item.target?.rest||ex.defaultRest||90)} rest</div><div class="meta">${muscleName(ex.primaryMuscle)} · ${esc(ex.equipment||"")} · ${trackingLabel(ex.trackingType)}</div></div><button class="icon-btn exercise-menu" data-item="${item.id}" type="button">•••</button></div></div><div class="exercise-body">
      ${ex.notes?`<div class="note-box"><strong>Exercise note:</strong> ${esc(ex.notes)}</div>`:""}
      <div class="previous"><strong>Previous:</strong> ${previousText(prev,ex)}<br><strong>Suggested:</strong> ${esc(suggestion)}</div>
      <div class="set-head"><span>Set</span><span>Type</span><span>${loadHeader(ex)}</span><span>${repHeader(ex)}</span><span>${state.settings.trackRir?"RIR":""}</span><span>✓</span></div>
      <div id="sets_${item.id}">${sets.map((st,i)=>liveSetRow(ex,st,i)).join("")}</div>
      <div class="exercise-actions"><button class="btn ghost small-btn add-set" data-item="${item.id}" type="button">+ Set</button><button class="btn ghost small-btn add-warmup" data-item="${item.id}" type="button">+ Warm-up</button><button class="btn ghost small-btn remove-last-set" data-item="${item.id}" type="button">− Set</button><button class="btn ghost small-btn rest-now" data-item="${item.id}" type="button">Rest</button></div>
      <div class="form-grid"><label class="check-chip"><input class="tech-good" data-item="${item.id}" type="checkbox" ${item.techniqueGood!==false?"checked":""}><span>Technique good</span></label><label>Pain / discomfort<select class="pain-select" data-item="${item.id}"><option value="none" ${item.pain==="none"?"selected":""}>None</option><option value="mild" ${item.pain==="mild"?"selected":""}>Mild</option><option value="stop" ${item.pain==="stop"?"selected":""}>Stop exercise</option></select></label></div>
      ${item.notes?`<div class="note-box"><strong>Session note:</strong> ${esc(item.notes)}</div>`:""}
    </div></section>`;
  }
  function loadHeader(ex){if(["reps_only","bodyweight_reps","duration"].includes(ex.trackingType))return "Load";if(ex.trackingType==="assisted_bodyweight")return `Assist ${weightUnit()}`;if(ex.trackingType==="bodyweight_added")return `+${weightUnit()}`;return weightUnit();}
  function repHeader(ex){if(isDurationBased(ex))return "Sec";if(ex.trackingType==="distance_duration")return "Km";return "Reps";}
  function liveSetRow(ex,s,i){const second=isDurationBased(ex)?s.durationSec:ex.trackingType==="distance_duration"?s.distanceKm:s.reps;const loadShown=s.loadKg?unitWeight(s.loadKg):"";return `<div class="set-row" data-set="${s.id}"><span class="set-num">${i+1}</span><select class="set-type" data-set="${s.id}">${setTypes.map(([v,l])=>`<option value="${v}" ${s.type===v?"selected":""}>${l}</option>`).join("")}</select><input class="set-load" data-set="${s.id}" inputmode="decimal" type="number" step="0.5" min="0" value="${esc(loadShown)}" placeholder="${["reps_only","bodyweight_reps","duration"].includes(ex.trackingType)?"—":weightUnit()}"><input class="set-reps" data-set="${s.id}" inputmode="decimal" type="number" step="${ex.trackingType==="distance_duration"?"0.1":"1"}" min="0" value="${second||""}" placeholder="${repHeader(ex)}"><input class="set-rir" data-set="${s.id}" inputmode="numeric" type="number" min="0" max="5" step="1" value="${s.rir??""}" ${state.settings.trackRir&&s.type!=="warmup"?"":"disabled"}><input class="done-check" data-set="${s.id}" type="checkbox" ${s.complete?"checked":""} aria-label="Set complete"></div>`;}

  function wireLiveExercise(session,item,idx){const ex=getExercise(item.exerciseId)||item.exerciseSnapshot;const root=byId(`sets_${item.id}`);
    root.querySelectorAll(".set-type").forEach(el=>el.addEventListener("change",()=>{const st=item.sets.find(x=>x.id===el.dataset.set);st.type=el.value;if(st.type==="warmup")st.rir=null;save();renderLiveSession(session);}));
    root.querySelectorAll(".set-load").forEach(el=>el.addEventListener("change",()=>{const st=item.sets.find(x=>x.id===el.dataset.set);st.loadKg=Math.max(0,toKg(el.value));save();}));
    root.querySelectorAll(".set-reps").forEach(el=>el.addEventListener("change",()=>{const st=item.sets.find(x=>x.id===el.dataset.set);if(isDurationBased(ex))st.durationSec=Math.max(0,num(el.value));else if(ex.trackingType==="distance_duration")st.distanceKm=Math.max(0,num(el.value));else st.reps=Math.max(0,num(el.value));save();}));
    root.querySelectorAll(".set-rir").forEach(el=>el.addEventListener("change",()=>{const st=item.sets.find(x=>x.id===el.dataset.set);st.rir=el.value===""?null:clamp(el.value,0,5);save();}));
    root.querySelectorAll(".done-check").forEach(el=>el.addEventListener("change",()=>{const st=item.sets.find(x=>x.id===el.dataset.set);st.complete=el.checked;if(st.complete&&state.settings.autoRest&&shouldStartRest(session,item,idx))startRestTimer(item.target?.rest||ex.defaultRest||90,ex.name);save();renderLiveSession(session);}));
    document.querySelector(`.add-set[data-item="${item.id}"]`).addEventListener("click",()=>{item.sets.push(newSet("normal"));save();renderLiveSession(session);});
    document.querySelector(`.add-warmup[data-item="${item.id}"]`).addEventListener("click",()=>{item.sets.unshift(newSet("warmup"));save();renderLiveSession(session);});
    document.querySelector(`.remove-last-set[data-item="${item.id}"]`).addEventListener("click",()=>{if(item.sets.length<=1)return showToast("Keep at least one set.");item.sets.pop();save();renderLiveSession(session);});
    document.querySelector(`.rest-now[data-item="${item.id}"]`).addEventListener("click",()=>startRestTimer(item.target?.rest||ex.defaultRest||90,ex.name));
    document.querySelector(`.tech-good[data-item="${item.id}"]`).addEventListener("change",e=>{item.techniqueGood=e.target.checked;save();});
    document.querySelector(`.pain-select[data-item="${item.id}"]`).addEventListener("change",e=>{item.pain=e.target.value;save();if(e.target.value==="stop")showToast("Stop this exercise and choose a pain-free substitute.");});
    document.querySelector(`.exercise-menu[data-item="${item.id}"]`).addEventListener("click",()=>openExerciseSessionMenu(session,item,idx));
  }
  function shouldStartRest(session,item,idx){if(!item.supersetGroup)return true;const same=session.items.map((it,i)=>({it,i})).filter(x=>x.it.supersetGroup===item.supersetGroup);return same.length?idx===same[same.length-1].i:true;}
  function previousText(prev,ex){if(!prev)return "No previous logged session";const sets=workingSets(prev);if(!sets.length)return "No completed working sets";const load=sets.map(s=>s.loadKg).filter(v=>v>0);const loadText=load.length?`${unitWeight(Math.max(...load))} ${weightUnit()}`:(ex.trackingType.includes("bodyweight")?"Bodyweight":"—");const reps=sets.map(s=>isDurationBased(ex)?`${s.durationSec}s`:s.reps).join(" / ");return `${loadText} · ${reps}`;}
  function suggestLoad(ex,item,prev){if(!prev)return "Choose a conservative load and establish a baseline.";if(prev.pain==="stop")return "Use a pain-free substitute before progressing.";if(prev.techniqueGood===false)return "Repeat or reduce load until technique is clean.";const sets=workingSets(prev);if(!sets.length)return "Repeat your last planned load.";const maxRep=item.target?.max||ex.defaultMax;const top=sets.length>=(item.target?.sets||sets.length)&&sets.slice(0,item.target?.sets||sets.length).every(s=>isDurationBased(ex)?s.durationSec>=maxRep:s.reps>=maxRep);const rirOkay=sets.every(s=>s.rir==null||s.rir>=1);const load=Math.max(0,...sets.map(s=>s.loadKg||0));if(top&&rirOkay&&num(ex.incrementKg)>0){const next=load+num(ex.incrementKg);return ex.trackingType==="bodyweight_added"?`Try bodyweight + ${unitWeight(next)} ${weightUnit()}.`:`Try ${unitWeight(next)} ${weightUnit()}.`;}return load?`Stay at ${unitWeight(load)} ${weightUnit()} and add reps.`:"Add reps before adding load.";}
  function openExerciseSessionMenu(session,item,idx){const ex=getExercise(item.exerciseId)||item.exerciseSnapshot;openModal("Exercise options",ex.name,`<div class="stack"><button class="btn ghost" id="substituteBtn" type="button">Substitute for this workout</button><button class="btn ghost" id="noteItemBtn" type="button">Add / edit session note</button><label>Superset group<input id="supersetInput" value="${esc(item.supersetGroup||"")}" placeholder="e.g. A"></label><button class="btn ghost" id="saveSupersetBtn" type="button">Save superset group</button><button class="btn danger" id="removeExerciseSessionBtn" type="button">Remove from workout</button></div>`,"");
    byId("substituteBtn").addEventListener("click",()=>{closeModal();openExercisePicker(exId=>{const replacement=getExercise(exId);item.substitutedForExerciseId=item.exerciseId;item.exerciseId=exId;item.exerciseSnapshot=snapshotExercise(replacement);save();renderLiveSession(session);},"Substitute exercise",item.exerciseId);});
    byId("noteItemBtn").addEventListener("click",()=>{closeModal();openTextModal("Exercise session note",item.notes||"",v=>{item.notes=v;save();renderLiveSession(session);});});
    byId("saveSupersetBtn").addEventListener("click",()=>{item.supersetGroup=byId("supersetInput").value.trim().toUpperCase().slice(0,4);save();closeModal();renderLiveSession(session);});
    byId("removeExerciseSessionBtn").addEventListener("click",()=>{if(!confirm(`Remove ${ex.name} from this workout?`))return;session.items.splice(idx,1);save();closeModal();renderLiveSession(session);});
  }
  function finishSession(s,status){const completed=s.items.reduce((n,i)=>n+workingSets(i).length,0),total=s.items.reduce((n,i)=>n+allWorkingSets(i).length,0);const aIncomplete=s.items.some(i=>i.target?.priority==="A"&&workingSets(i).length<Math.max(1,i.target.sets));if(status==="complete"&&(total&&completed/total<.9||aIncomplete)){if(!confirm("Less than 90% of prescribed work or a Priority-A exercise is incomplete. Mark complete anyway?"))return;}s.status=status;s.endTime=Date.now();state.currentWorkoutId=null;save();stopElapsedTimer();const prs=sessionPRs(s);navigate("history");showToast(prs.length?`${prs.length} PR${prs.length>1?"s":""} recorded.`:`Workout ${status}.`);}
  function sessionPRs(session){
    const result=[];session.items.forEach(item=>{
      const cur=workingSets(item);if(!cur.length)return;const priorSets=allPriorSets(item.exerciseId,addDays(session.date,-1),session.id);
      const priorMaxLoad=Math.max(0,...priorSets.map(s=>s.loadKg||0)),curMaxLoad=Math.max(0,...cur.map(s=>s.loadKg||0));if(curMaxLoad>priorMaxLoad&&curMaxLoad>0)result.push({exerciseId:item.exerciseId,type:"Weight PR",value:curMaxLoad});
      const priorE=Math.max(0,...priorSets.map(s=>e1rm(s.loadKg,s.reps))),curE=Math.max(0,...cur.map(s=>e1rm(s.loadKg,s.reps)));if(curE>priorE&&curE>0)result.push({exerciseId:item.exerciseId,type:"e1RM PR",value:curE});
      cur.forEach(st=>{if(st.loadKg<=0||st.reps<=0)return;const bestPriorAtLoad=Math.max(0,...priorSets.filter(p=>Math.abs((p.loadKg||0)-st.loadKg)<.01).map(p=>p.reps||0));if(st.reps>bestPriorAtLoad&&bestPriorAtLoad>0)result.push({exerciseId:item.exerciseId,type:"Rep PR",value:st.reps,loadKg:st.loadKg});});
      const curVolume=cur.reduce((a,x)=>a+setVolume(x),0);const priorVolumes=state.sessions.filter(s=>s.id!==session.id&&s.date<session.date&&["complete","shortened"].includes(s.status)).map(s=>s.items.filter(i=>i.exerciseId===item.exerciseId).flatMap(i=>workingSets(i)).reduce((a,x)=>a+setVolume(x),0));const bestPriorVolume=Math.max(0,...priorVolumes);if(curVolume>bestPriorVolume&&bestPriorVolume>0)result.push({exerciseId:item.exerciseId,type:"Volume PR",value:curVolume});
    });return dedupePRs(result);
  }
  function dedupePRs(list){const seen=new Set();return list.filter(x=>{const k=`${x.exerciseId}|${x.type}`;if(seen.has(k))return false;seen.add(k);return true;});}
  function allPriorSets(exId,beforeDate,excludeId){return state.sessions.filter(s=>s.id!==excludeId&&s.date<=beforeDate&&["complete","shortened"].includes(s.status)).flatMap(s=>s.items.filter(i=>i.exerciseId===exId).flatMap(i=>workingSets(i)));}
  function startElapsedTimer(s){stopElapsedTimer();if(s.endTime)return;elapsedInterval=setInterval(()=>{const el=byId("elapsedTimer");if(el)el.textContent=durationText(sessionDuration(s));},1000);}
  function stopElapsedTimer(){if(elapsedInterval)clearInterval(elapsedInterval);elapsedInterval=null;}
  function startRestTimer(sec,label){stopRestTimer();restEndAt=Date.now()+sec*1000;byId("restTimerLabel").textContent=label;byId("restTimer").classList.remove("hidden");tickRest();restInterval=setInterval(tickRest,250);}
  function tickRest(){const left=Math.max(0,Math.ceil((restEndAt-Date.now())/1000));byId("restTimerValue").textContent=restText(left);if(left<=0){stopRestTimer();showToast("Rest complete.");if("vibrate" in navigator)navigator.vibrate?.([100,60,100]);}}
  function stopRestTimer(){if(restInterval)clearInterval(restInterval);restInterval=null;byId("restTimer").classList.add("hidden");}

  // ---------- PROGRAMS + LIBRARY ----------
  function renderPrograms(){const p=state.programs[selectedProgramId]||activeProgram()||Object.values(state.programs)[0];if(p)selectedProgramId=p.id;
    view.innerHTML=`<div class="stack"><section class="card"><div class="row"><div><p class="eyebrow">Program builder</p><h2>${p?esc(p.name):"No program"}</h2><p class="meta">${p?.description?esc(p.description):"Create and edit reusable workout schedules."}</p></div><button class="btn primary" id="newProgramBtn" type="button">+ Program</button></div><div class="tabs" style="margin-top:12px">${Object.values(state.programs).map(x=>`<button class="tab ${x.id===selectedProgramId?"active":""}" data-prog="${x.id}" type="button">${esc(x.name)}</button>`).join("")}</div></section>
      ${p?`<section class="card"><div class="wrap"><button class="btn ${p.id===state.settings.activeProgramId?"secondary":"ghost"}" id="activateProgramBtn" type="button">${p.id===state.settings.activeProgramId?"Active program":"Make active"}</button><button class="btn ghost" id="editProgramBtn" type="button">Edit details</button><button class="btn ghost" id="addDayBtn" type="button">+ Day</button><button class="btn ghost" id="duplicateProgramBtn" type="button">Duplicate</button>${Object.keys(state.programs).length>1?`<button class="btn danger" id="deleteProgramBtn" type="button">Delete</button>`:""}</div></section>`:""}
      ${p?.days.map((d,di)=>programDayCard(p,d,di)).join("")||`<section class="card empty">No program days yet.</section>`}
      <section class="card"><div class="section-title"><h2>Exercise Library</h2><button class="btn primary small-btn" id="addExerciseLibraryBtn" type="button">+ Exercise</button></div><p class="meta">${Object.values(state.exercises).filter(e=>!e.archived).length} active exercises · Built-in and custom</p><div class="wrap"><button class="btn ghost small-btn" id="openLibraryBtn" type="button">Open library</button></div></section>
    </div>`;
    document.querySelectorAll("[data-prog]").forEach(b=>b.addEventListener("click",()=>{selectedProgramId=b.dataset.prog;renderPrograms();}));
    byId("newProgramBtn").addEventListener("click",()=>openProgramDetailsModal(null));
    if(!p)return;
    byId("activateProgramBtn").addEventListener("click",()=>{state.settings.activeProgramId=p.id;save();renderPrograms();showToast("Active program updated.");});
    byId("editProgramBtn").addEventListener("click",()=>openProgramDetailsModal(p));
    byId("addDayBtn").addEventListener("click",()=>openProgramDayModal(p,null));
    byId("duplicateProgramBtn").addEventListener("click",()=>{const cp=clone(p);cp.id=uid("prog");cp.name=`${p.name} Copy`;cp.days.forEach(d=>{d.id=uid("day");d.items.forEach(i=>i.id=uid("pi"));});state.programs[cp.id]=cp;selectedProgramId=cp.id;save();renderPrograms();});
    byId("deleteProgramBtn")?.addEventListener("click",()=>{if(!confirm(`Delete ${p.name}? Historical workouts remain.`))return;delete state.programs[p.id];if(state.settings.activeProgramId===p.id)state.settings.activeProgramId=Object.keys(state.programs)[0];selectedProgramId=state.settings.activeProgramId;save();renderPrograms();});
    document.querySelectorAll(".edit-day").forEach(b=>b.addEventListener("click",()=>openProgramDayModal(p,p.days.find(d=>d.id===b.dataset.day))));
    document.querySelectorAll(".add-program-ex").forEach(b=>b.addEventListener("click",()=>{const d=p.days.find(x=>x.id===b.dataset.day);openExercisePicker(exId=>openProgramItemModal(p,d,null,exId),"Add exercise");}));
    document.querySelectorAll(".edit-program-item").forEach(b=>b.addEventListener("click",()=>{const d=p.days.find(x=>x.id===b.dataset.day),it=d.items.find(x=>x.id===b.dataset.item);openProgramItemModal(p,d,it,it.exerciseId);}));
    document.querySelectorAll(".move-item").forEach(b=>b.addEventListener("click",()=>moveProgramItem(p,b.dataset.day,b.dataset.item,Number(b.dataset.dir))));
    byId("addExerciseLibraryBtn").addEventListener("click",()=>openExerciseModal(null));byId("openLibraryBtn").addEventListener("click",()=>openLibraryModal());
  }
  function programDayCard(p,d,di){return `<section class="card program-day"><div class="program-day-head"><div class="row"><div><h3>${esc(d.name)}</h3><div class="meta">${weekdayName(d.weekday)} · ${d.items.length} exercises · ${d.items.reduce((a,x)=>a+x.sets,0)} sets</div></div><button class="btn ghost small-btn edit-day" data-day="${d.id}" type="button">Edit</button></div></div><div class="program-items">${d.items.map((it,ii)=>{const ex=getExercise(it.exerciseId);return `<div class="program-item"><div class="row start"><div><strong>${esc(ex?.name||"Missing exercise")}</strong><div class="meta">${it.sets} × ${it.min}–${it.max} · ${restText(it.rest)} · Priority ${it.priority}${it.supersetGroup?` · SS ${esc(it.supersetGroup)}`:""}</div></div><div class="wrap"><button class="btn ghost small-btn move-item" data-day="${d.id}" data-item="${it.id}" data-dir="-1" type="button" ${ii===0?"disabled":""}>↑</button><button class="btn ghost small-btn move-item" data-day="${d.id}" data-item="${it.id}" data-dir="1" type="button" ${ii===d.items.length-1?"disabled":""}>↓</button><button class="btn ghost small-btn edit-program-item" data-day="${d.id}" data-item="${it.id}" type="button">Edit</button></div></div></div>`;}).join("")}<button class="btn ghost add-program-ex" data-day="${d.id}" type="button" style="margin:10px 0">+ Exercise</button></div></section>`;}
  function moveProgramItem(p,dayId,itemId,dir){const d=p.days.find(x=>x.id===dayId),i=d.items.findIndex(x=>x.id===itemId),j=i+dir;if(i<0||j<0||j>=d.items.length)return;[d.items[i],d.items[j]]=[d.items[j],d.items[i]];p.updatedAt=Date.now();save();renderPrograms();}
  function openProgramDetailsModal(p){const creating=!p;openModal(creating?"New program":"Program details",creating?"Create reusable program":p.name,`<div class="stack"><label>Name<input id="programName" value="${esc(p?.name||"")}" maxlength="60"></label><label>Description<textarea id="programDesc">${esc(p?.description||"")}</textarea></label></div>`,`<button class="btn primary" id="saveProgramDetails" type="button">${creating?"Create":"Save"}</button>`);byId("saveProgramDetails").addEventListener("click",()=>{const name=byId("programName").value.trim();if(!name)return showToast("Program name is required.");if(creating){const id=uid("prog");state.programs[id]={id,name,description:byId("programDesc").value.trim(),createdAt:Date.now(),updatedAt:Date.now(),days:[]};selectedProgramId=id;}else{p.name=name;p.description=byId("programDesc").value.trim();p.updatedAt=Date.now();}save();closeModal();renderPrograms();});}
  function openProgramDayModal(p,d){const creating=!d;openModal(creating?"Add program day":"Edit program day",p.name,`<div class="stack"><label>Day name<input id="dayName" value="${esc(d?.name||"")}" maxlength="50"></label><label>Scheduled weekday<select id="dayWeekday">${[[0,"Sunday"],[1,"Monday"],[2,"Tuesday"],[3,"Wednesday"],[4,"Thursday"],[5,"Friday"],[6,"Saturday"],[-1,"Unscheduled"]].map(([v,n])=>`<option value="${v}" ${Number(d?.weekday)===v?"selected":""}>${n}</option>`).join("")}</select></label>${!creating?`<button class="btn danger" id="deleteDayBtn" type="button">Delete day</button>`:""}</div>`,`<button class="btn primary" id="saveDayBtn" type="button">Save</button>`);byId("saveDayBtn").addEventListener("click",()=>{const name=byId("dayName").value.trim();if(!name)return showToast("Day name is required.");if(creating)p.days.push({id:uid("day"),name,weekday:Number(byId("dayWeekday").value),items:[]});else{d.name=name;d.weekday=Number(byId("dayWeekday").value);}p.updatedAt=Date.now();save();closeModal();renderPrograms();});byId("deleteDayBtn")?.addEventListener("click",()=>{if(!confirm("Delete this program day? Historical workouts remain."))return;p.days=p.days.filter(x=>x.id!==d.id);save();closeModal();renderPrograms();});}
  function openProgramItemModal(p,d,it,exerciseId){const ex=getExercise(exerciseId);const v=it||{sets:3,min:ex.defaultMin,max:ex.defaultMax,rest:ex.defaultRest,priority:"B",rirMin:1,rirMax:2,supersetGroup:"",notes:""};openModal(it?"Edit exercise prescription":"Add exercise",ex.name,`<div class="form-grid"><label>Sets<input id="piSets" type="number" min="1" max="20" value="${v.sets}"></label><label>Min reps / sec<input id="piMin" type="number" min="1" max="300" value="${v.min}"></label><label>Max reps / sec<input id="piMax" type="number" min="1" max="300" value="${v.max}"></label><label>Rest seconds<input id="piRest" type="number" min="0" max="900" value="${v.rest}"></label><label>Priority<select id="piPriority">${["A","B","C"].map(x=>`<option ${v.priority===x?"selected":""}>${x}</option>`).join("")}</select></label><label>Superset group<input id="piSS" value="${esc(v.supersetGroup||"")}" placeholder="A"></label><label>RIR min<input id="piRirMin" type="number" min="0" max="5" value="${v.rirMin??1}"></label><label>RIR max<input id="piRirMax" type="number" min="0" max="5" value="${v.rirMax??2}"></label></div><label>Notes<textarea id="piNotes">${esc(v.notes||"")}</textarea></label>${it?`<button class="btn danger" id="removeProgramItem" type="button">Remove exercise</button>`:""}`,`<button class="btn primary" id="saveProgramItem" type="button">Save</button>`);byId("saveProgramItem").addEventListener("click",()=>{const obj=it||{id:uid("pi"),exerciseId};obj.sets=clamp(byId("piSets").value,1,20)||3;obj.min=clamp(byId("piMin").value,1,300)||ex.defaultMin;obj.max=Math.max(obj.min,clamp(byId("piMax").value,1,300)||ex.defaultMax);obj.rest=clamp(byId("piRest").value,0,900)??ex.defaultRest;obj.priority=byId("piPriority").value;obj.supersetGroup=byId("piSS").value.trim().toUpperCase().slice(0,4);obj.rirMin=clamp(byId("piRirMin").value,0,5)??1;obj.rirMax=clamp(byId("piRirMax").value,0,5)??2;obj.notes=byId("piNotes").value.trim();if(!it)d.items.push(obj);p.updatedAt=Date.now();save();closeModal();renderPrograms();});byId("removeProgramItem")?.addEventListener("click",()=>{d.items=d.items.filter(x=>x.id!==it.id);save();closeModal();renderPrograms();});}

  function openLibraryModal(){openModal("Exercise Library","Built-in + custom exercises",libraryHTML(),`<button class="btn primary" id="libAddBtn" type="button">+ Custom exercise</button>`);wireLibraryModal();byId("libAddBtn").addEventListener("click",()=>{closeModal();openExerciseModal(null);});}
  function libraryHTML(){const list=Object.values(state.exercises).filter(e=>(libraryMuscle==="all"||e.primaryMuscle===libraryMuscle)&&(e.name.toLowerCase().includes(librarySearch.toLowerCase()))).sort((a,b)=>a.name.localeCompare(b.name));return `<div class="form-grid"><label>Search<input id="librarySearchInput" value="${esc(librarySearch)}" placeholder="Exercise name"></label><label>Primary muscle<select id="libraryMuscleSelect"><option value="all">All muscles</option>${SEED.muscles.map(m=>`<option value="${m.id}" ${libraryMuscle===m.id?"selected":""}>${m.name}</option>`).join("")}</select></label></div><div class="list">${list.map(e=>`<div class="list-row click-row library-row" data-ex="${e.id}"><div><strong>${esc(e.name)}</strong><div class="meta">${muscleName(e.primaryMuscle)} · ${esc(e.equipment)} · ${trackingLabel(e.trackingType)}${e.archived?" · Archived":""}</div></div><span class="pill ${e.builtIn?"neutral":"good"}">${e.builtIn?"Built-in":"Custom"}</span></div>`).join("")||`<div class="empty">No exercises match.</div>`}</div>`;}
  function wireLibraryModal(){byId("librarySearchInput")?.addEventListener("input",e=>{librarySearch=e.target.value;modalBody.innerHTML=libraryHTML();wireLibraryModal();});byId("libraryMuscleSelect")?.addEventListener("change",e=>{libraryMuscle=e.target.value;modalBody.innerHTML=libraryHTML();wireLibraryModal();});document.querySelectorAll(".library-row").forEach(r=>r.addEventListener("click",()=>{const ex=getExercise(r.dataset.ex);closeModal();openExerciseModal(ex);}));}
  function openExerciseModal(ex){const creating=!ex;const v=ex||{name:"",primaryMuscle:"chest",secondaryMuscles:[],equipment:"Other",trackingType:"weight_reps",defaultMin:8,defaultMax:12,defaultRest:90,incrementKg:2.5,notes:"",archived:false};openModal(creating?"New exercise":"Edit exercise",creating?"Add to your library":v.name,`<div class="stack"><label>Name<input id="exName" value="${esc(v.name)}" maxlength="70"></label><div class="form-grid"><label>Primary muscle<select id="exPrimary">${SEED.muscles.map(m=>`<option value="${m.id}" ${v.primaryMuscle===m.id?"selected":""}>${m.name}</option>`).join("")}</select></label><label>Equipment<select id="exEquipment">${equipments.map(x=>`<option ${v.equipment===x?"selected":""}>${x}</option>`).join("")}</select></label><label>Tracking type<select id="exTracking">${trackingTypes.map(([id,n])=>`<option value="${id}" ${v.trackingType===id?"selected":""}>${n}</option>`).join("")}</select></label><label>Load increment (${weightUnit()})<input id="exIncrement" type="number" step="0.5" min="0" value="${unitWeight(v.incrementKg||0)}"></label><label>Default min<input id="exMin" type="number" min="1" max="300" value="${v.defaultMin}"></label><label>Default max<input id="exMax" type="number" min="1" max="300" value="${v.defaultMax}"></label><label>Default rest (sec)<input id="exRest" type="number" min="0" max="900" value="${v.defaultRest}"></label></div><div><p class="meta" style="font-weight:800">Secondary muscles</p><div class="checks">${SEED.muscles.map(m=>`<label class="check-chip"><input class="secondary-muscle" type="checkbox" value="${m.id}" ${(v.secondaryMuscles||[]).includes(m.id)?"checked":""}><span>${m.name}</span></label>`).join("")}</div></div><label>Persistent exercise note<textarea id="exNotes">${esc(v.notes||"")}</textarea></label>${!creating?`<label class="check-chip"><input id="exArchived" type="checkbox" ${v.archived?"checked":""}><span>Archived</span></label>`:""}</div>`,`<button class="btn primary" id="saveExerciseBtn" type="button">${creating?"Create exercise":"Save"}</button>`);byId("saveExerciseBtn").addEventListener("click",()=>{const name=byId("exName").value.trim();if(!name)return showToast("Exercise name is required.");const primary=byId("exPrimary").value;const second=[...document.querySelectorAll(".secondary-muscle:checked")].map(x=>x.value).filter(x=>x!==primary);const obj=ex||{id:uid("ex"),builtIn:false,createdAt:Date.now()};Object.assign(obj,{name,primaryMuscle:primary,secondaryMuscles:second,equipment:byId("exEquipment").value,trackingType:byId("exTracking").value,incrementKg:toKg(byId("exIncrement").value),defaultMin:clamp(byId("exMin").value,1,300)||8,defaultMax:clamp(byId("exMax").value,1,300)||12,defaultRest:clamp(byId("exRest").value,0,900)??90,notes:byId("exNotes").value.trim(),archived:byId("exArchived")?.checked||false,updatedAt:Date.now()});if(obj.defaultMax<obj.defaultMin)obj.defaultMax=obj.defaultMin;state.exercises[obj.id]=obj;save();closeModal();if(activeView==="programs")renderPrograms();else render();showToast(creating?"Exercise created.":"Exercise saved.");});}
  function openExercisePicker(onPick,title="Choose exercise",excludeId=null){const active=Object.values(state.exercises).filter(e=>!e.archived&&e.id!==excludeId).sort((a,b)=>a.name.localeCompare(b.name));openModal(title,"Exercise Library",`<label>Search<input id="pickerSearch" placeholder="Search exercises"></label><div class="list" id="pickerList">${pickerRows(active)}</div>`,`<button class="btn ghost" id="pickerNewExercise" type="button">+ Create exercise</button>`);const filter=()=>{const q=byId("pickerSearch").value.toLowerCase();byId("pickerList").innerHTML=pickerRows(active.filter(e=>e.name.toLowerCase().includes(q)));wirePickRows();};const wirePickRows=()=>document.querySelectorAll(".pick-exercise").forEach(r=>r.addEventListener("click",()=>{const id=r.dataset.ex;closeModal();onPick(id);}));byId("pickerSearch").addEventListener("input",filter);byId("pickerNewExercise").addEventListener("click",()=>{closeModal();openExerciseModal(null);});wirePickRows();}
  function pickerRows(list){return list.map(e=>`<div class="list-row click-row pick-exercise" data-ex="${e.id}"><div><strong>${esc(e.name)}</strong><div class="meta">${muscleName(e.primaryMuscle)} · ${esc(e.equipment)}</div></div><span>›</span></div>`).join("")||`<div class="empty">No matching exercises.</div>`;}

  // ---------- HISTORY ----------
  function renderHistory(){
    const monthDate=dateObj(historyMonth),monthLabel=monthDate.toLocaleDateString(undefined,{month:"long",year:"numeric"});
    const matches=s=>{
      if(historyProgramFilter!=="all"&&s.programId!==historyProgramFilter)return false;
      if(historyExerciseFilter!=="all"&&!s.items.some(i=>i.exerciseId===historyExerciseFilter))return false;
      if(historyMuscleFilter!=="all"&&!s.items.some(i=>{const ex=i.exerciseSnapshot||getExercise(i.exerciseId);return ex&&(ex.primaryMuscle===historyMuscleFilter||(ex.secondaryMuscles||[]).includes(historyMuscleFilter));}))return false;
      return true;
    };
    const monthSessions=state.sessions.filter(s=>s.date.slice(0,7)===historyMonth.slice(0,7)&&matches(s)).sort((a,b)=>b.date.localeCompare(a.date)||(b.startTime||0)-(a.startTime||0));
    const activeExercises=Object.values(state.exercises).filter(e=>!e.archived).sort((a,b)=>a.name.localeCompare(b.name));
    view.innerHTML=`<div class="stack"><section class="card"><div class="calendar-head"><button class="icon-btn" id="prevMonth" type="button">‹</button><div><p class="eyebrow">Workout history</p><h2>${monthLabel}</h2></div><button class="icon-btn" id="nextMonth" type="button">›</button></div>${calendarHTML(historyMonth)}</section><section class="card"><div class="section-title"><h2>Filters</h2><button class="btn ghost small-btn" id="clearHistoryFilters" type="button">Clear</button></div><div class="form-grid three" style="margin-top:10px"><label>Exercise<select id="historyExercise"><option value="all">All exercises</option>${activeExercises.map(e=>`<option value="${e.id}" ${historyExerciseFilter===e.id?"selected":""}>${esc(e.name)}</option>`).join("")}</select></label><label>Muscle<select id="historyMuscle"><option value="all">All muscles</option>${SEED.muscles.map(m=>`<option value="${m.id}" ${historyMuscleFilter===m.id?"selected":""}>${m.name}</option>`).join("")}</select></label><label>Program<select id="historyProgram"><option value="all">All programs</option>${Object.values(state.programs).map(p=>`<option value="${p.id}" ${historyProgramFilter===p.id?"selected":""}>${esc(p.name)}</option>`).join("")}</select></label></div></section><section class="card"><div class="section-title"><h2>Sessions</h2><span class="meta">${monthSessions.length} workouts</span></div><div class="list">${monthSessions.map(sessionHistoryRow).join("")||`<div class="empty">No workouts match these filters.</div>`}</div></section></div>`;
    byId("prevMonth").addEventListener("click",()=>{const d=dateObj(historyMonth);d.setMonth(d.getMonth()-1);historyMonth=startOfMonth(isoFromDate(d));renderHistory();});
    byId("nextMonth").addEventListener("click",()=>{const d=dateObj(historyMonth);d.setMonth(d.getMonth()+1);historyMonth=startOfMonth(isoFromDate(d));renderHistory();});
    byId("historyExercise").addEventListener("change",e=>{historyExerciseFilter=e.target.value;renderHistory();});byId("historyMuscle").addEventListener("change",e=>{historyMuscleFilter=e.target.value;renderHistory();});byId("historyProgram").addEventListener("change",e=>{historyProgramFilter=e.target.value;renderHistory();});byId("clearHistoryFilters").addEventListener("click",()=>{historyExerciseFilter=historyMuscleFilter=historyProgramFilter="all";renderHistory();});
    document.querySelectorAll(".history-session").forEach(r=>r.addEventListener("click",()=>openHistorySession(r.dataset.session)));
  }
  function calendarHTML(monthStart){const d=dateObj(monthStart),year=d.getFullYear(),month=d.getMonth();const first=new Date(year,month,1,12),last=new Date(year,month+1,0,12);const monday=state.settings.weekStarts!=="sunday";let offset=first.getDay();if(monday)offset=offset===0?6:offset-1;const labels=monday?["M","T","W","T","F","S","S"]:["S","M","T","W","T","F","S"];const cells=[];for(let i=0;i<42;i++){const dayNum=i-offset+1;const cd=new Date(year,month,dayNum,12);const iso=isoFromDate(cd),inMonth=cd.getMonth()===month;const ss=state.sessions.filter(s=>s.date===iso);cells.push(`<button class="cal-day ${!inMonth?"muted-day":""} ${iso===isoToday()?"today":""}" type="button" data-cal-date="${iso}" disabled><strong>${cd.getDate()}</strong>${ss.length?`<div class="dots">${ss.slice(0,3).map(s=>`<i class="dot ${s.status==="shortened"?"short":s.status==="skipped"?"skip":""}"></i>`).join("")}</div>`:""}</button>`);}return `<div class="calendar">${labels.map(x=>`<div class="cal-label">${x}</div>`).join("")}${cells.join("")}</div>`;}
  function sessionHistoryRow(s){const sets=s.items.reduce((n,i)=>n+workingSets(i).length,0),vol=s.items.reduce((n,i)=>n+workingSets(i).reduce((a,x)=>a+setVolume(x),0),0);return `<div class="list-row click-row history-session" data-session="${s.id}"><div><strong>${esc(s.name)}</strong><div class="meta">${fmtDate(s.date)} · ${durationText(sessionDuration(s))} · ${sets} sets${vol?` · ${Math.round(unitWeight(vol))} ${weightUnit()}-reps`:""}</div></div><span class="pill ${s.status==="complete"?"good":s.status==="shortened"?"warn":"neutral"}">${cap(s.status)}</span></div>`;}
  function openHistorySession(id){const s=getSession(id);if(!s)return;const prs=sessionPRs(s);openModal("Workout history",`${s.name} · ${fmtDate(s.date)}`,`<div class="grid-3"><div class="metric"><span class="meta">Duration</span><strong>${durationText(sessionDuration(s))}</strong></div><div class="metric"><span class="meta">Working sets</span><strong>${s.items.reduce((n,i)=>n+workingSets(i).length,0)}</strong></div><div class="metric"><span class="meta">PRs</span><strong>${prs.length}</strong></div></div>${s.notes?`<div class="note-box">${esc(s.notes)}</div>`:""}<div class="list">${s.items.map(i=>{const ex=getExercise(i.exerciseId)||i.exerciseSnapshot;return `<div class="list-row"><div><strong>${esc(ex.name)}</strong><div class="meta">${workingSets(i).map(st=>setSummary(st,ex)).join(" · ")||"No completed working sets"}</div></div></div>`;}).join("")}</div>`,`<button class="btn ghost" id="editHistoryBtn" type="button">Edit workout</button><button class="btn danger" id="deleteHistoryBtn" type="button">Delete</button>`);byId("editHistoryBtn").addEventListener("click",()=>{state.currentWorkoutId=s.id;save();closeModal();navigate("train");});byId("deleteHistoryBtn").addEventListener("click",()=>{if(!confirm("Delete this historical workout?"))return;state.sessions=state.sessions.filter(x=>x.id!==s.id);save();closeModal();renderHistory();});}
  function setSummary(st,ex){if(isDurationBased(ex))return `${unitWeight(st.loadKg||0)}${weightUnit()} × ${st.durationSec}s`;if(ex.trackingType==="distance_duration")return `${st.distanceKm}km`;if(st.loadKg>0)return `${unitWeight(st.loadKg)}${weightUnit()}×${st.reps}`;return `${st.reps} reps`;}

  // ---------- PROGRESS / ANALYTICS ----------
  function renderProgress(){view.innerHTML=`<div class="stack"><section class="card"><div class="tabs">${[["overview","Overview"],["muscles","Muscles"],["exercise","Exercise"],["body","Body"],["goals","Goals"]].map(([id,n])=>`<button class="tab ${progressTab===id?"active":""}" data-progress-tab="${id}" type="button">${n}</button>`).join("")}</div></section><div id="progressContent">${progressTabHTML()}</div></div>`;document.querySelectorAll("[data-progress-tab]").forEach(b=>b.addEventListener("click",()=>{progressTab=b.dataset.progressTab;renderProgress();}));wireProgressTab();}
  function progressTabHTML(){if(progressTab==="muscles")return musclesHTML();if(progressTab==="exercise")return exerciseAnalyticsHTML();if(progressTab==="body")return bodyHTML();if(progressTab==="goals")return goalsHTML();return overviewHTML();}
  function overviewHTML(){const week=weekSummary(isoToday()),insights=buildInsights(),avgWeight=bodyAverage("weight",7),latestWaist=latestBody("waist"),recentPrs=recentPRs(30).slice(0,5);return `<section class="card hero"><div class="row"><div><p class="meta">This week</p><div class="big">${week.completed}/${week.scheduled}</div><p class="meta">scheduled workouts completed · ${week.shortened} shortened</p></div><span class="pill ${week.completed>=week.scheduled&&week.scheduled?"good":"neutral"}">${week.sets} working sets</span></div></section><section class="grid-2"><div class="metric"><span class="meta">7-day body weight</span><strong>${avgWeight?`${round1(avgWeight)} kg`:"—"}</strong></div><div class="metric"><span class="meta">Latest waist</span><strong>${latestWaist?`${round1(latestWaist.waist)} cm`:"—"}</strong></div></section><section class="card"><h2>Insights</h2><div class="stack" style="margin-top:10px">${insights.map(x=>`<div class="insight ${x.tone||""}"><strong>${esc(x.title)}</strong><div class="meta">${esc(x.text)}</div></div>`).join("")||`<div class="empty">Log more workouts to generate useful insights.</div>`}</div></section><section class="card"><div class="section-title"><h2>Recent PRs</h2><span class="meta">Last 30 days</span></div><div class="list">${recentPrs.map(p=>`<div class="list-row"><div><strong>${esc(getExercise(p.exerciseId)?.name||"Exercise")}</strong><div class="meta">${esc(p.type)} · ${fmtDate(p.date)}</div></div><span class="pill good">${p.display}</span></div>`).join("")||`<div class="empty">No PRs yet.</div>`}</div></section>`;}
  function weekSummary(date){const start=startOfWeek(date),end=addDays(start,6),p=activeProgram();const scheduled=p?p.days.filter(d=>d.weekday>=0).length:0;const ss=state.sessions.filter(s=>s.date>=start&&s.date<=end);return {scheduled,completed:ss.filter(s=>s.status==="complete").length,shortened:ss.filter(s=>s.status==="shortened").length,sets:ss.reduce((n,s)=>n+s.items.reduce((a,i)=>a+workingSets(i).length,0),0)};}
  function recentPRs(days){const cutoff=addDays(isoToday(),-(days-1)),out=[];state.sessions.filter(s=>s.date>=cutoff&&["complete","shortened"].includes(s.status)).sort((a,b)=>a.date.localeCompare(b.date)).forEach(s=>sessionPRs(s).forEach(p=>{let display="PR";if(p.type==="Weight PR")display=`${unitWeight(p.value)} ${weightUnit()}`;else if(p.type==="e1RM PR")display=`${round1(unitWeight(p.value))} ${weightUnit()}`;else if(p.type==="Rep PR")display=`${unitWeight(p.loadKg)} ${weightUnit()} × ${p.value}`;else if(p.type==="Volume PR")display=`${Math.round(unitWeight(p.value))}`;out.push({...p,date:s.date,display});}));return out.sort((a,b)=>b.date.localeCompare(a.date));}
  function buildInsights(){const out=[];const weekMus=muscleStatsForRange(startOfWeek(isoToday()),addDays(startOfWeek(isoToday()),6));const low=SEED.muscles.map(m=>({m,st:weekMus[m.id]||{direct:0,effective:0},target:state.settings.muscleTargets[m.id]||[0,999]})).filter(x=>x.target[0]>=6&&x.st.effective<x.target[0]*.65).sort((a,b)=>a.st.effective-b.st.effective).slice(0,2);low.forEach(x=>out.push({tone:"warn",title:`${x.m.name} below target`,text:`${round1(x.st.effective)} effective sets this week vs your ${x.target[0]}–${x.target[1]} target.`}));const push=sumMus(weekMus,["chest","front_delts","triceps"]),pull=sumMus(weekMus,["lats","upper_back","rear_delts","biceps"]);if(push&&pull){const ratio=push/pull;if(ratio>1.35)out.push({tone:"warn",title:"Push volume exceeds pull",text:`Push ${round1(push)} vs pull ${round1(pull)} effective sets this week.`});else if(ratio<.74)out.push({tone:"warn",title:"Pull volume exceeds push",text:`Pull ${round1(pull)} vs push ${round1(push)} effective sets this week.`});else out.push({tone:"good",title:"Push / pull balance looks reasonable",text:`Push ${round1(push)} vs pull ${round1(pull)} effective sets this week.`});}
    const shortened=state.sessions.filter(s=>["complete","shortened"].includes(s.status)).slice(-8).filter(s=>s.status==="shortened").length;if(shortened>=3)out.push({tone:"warn",title:"Frequent shortened workouts",text:`${shortened} of your last 8 logged workouts were shortened. Consider trimming lower-priority work.`});
    const plateaus=findPlateaus();plateaus.slice(0,2).forEach(p=>out.push({tone:"warn",title:`${p.name} plateau signal`,text:"Estimated 1RM has stayed within about 1% across the last six exposures."}));if(!out.length&&state.sessions.length)out.push({tone:"good",title:"Training data looks stable",text:"No major volume imbalance or repeated plateau signal detected from current data."});return out;}
  function sumMus(stats,ids){return ids.reduce((a,id)=>a+(stats[id]?.effective||0),0);}
  function findPlateaus(){return Object.values(state.exercises).map(ex=>{const pts=exerciseE1rmPoints(ex.id).slice(-6);if(pts.length<6)return null;const vals=pts.map(x=>x.value),avg=vals.reduce((a,b)=>a+b,0)/vals.length,spread=(Math.max(...vals)-Math.min(...vals))/avg;return spread<=.01?{id:ex.id,name:ex.name}:null;}).filter(Boolean);}

  function musclesHTML(){const start=startOfWeek(isoToday()),end=addDays(start,6),stats=muscleStatsForRange(start,end);return `<section class="card"><div class="section-title"><div><p class="eyebrow">Muscle analytics</p><h2>This week</h2></div><span class="meta">${fmtDate(start)} – ${fmtDate(end)}</span></div><div class="legend" style="margin-top:10px"><span>Low</span><i style="background:#dbeafe"></i><i style="background:#93c5fd"></i><i style="background:#3b82f6"></i><i style="background:#1d4ed8"></i><span>High</span></div><div class="body-map-wrap" style="margin-top:8px">${bodyMapSVG("front",stats)}${bodyMapSVG("back",stats)}</div><p class="meta">Schematic training map. Color intensity reflects effective sets relative to your weekly target.</p></section><section class="card"><div class="muscle-row" style="font-weight:850;color:var(--muted)"><span>Muscle</span><span>Direct</span><span>Effective</span><span>Target</span></div>${SEED.muscles.map(m=>{const x=stats[m.id]||{direct:0,effective:0},t=state.settings.muscleTargets[m.id]||[0,0],pct=t[0]?Math.min(100,x.effective/t[0]*100):0;return `<div class="muscle-row click-row muscle-detail" data-muscle="${m.id}"><div><strong>${m.name}</strong><div class="bar"><span style="width:${pct}%"></span></div></div><span>${round1(x.direct)}</span><span>${round1(x.effective)}</span><span>${t[0]}–${t[1]}</span></div>`;}).join("")}</section>`;}
  function muscleStatsForRange(start,end){const out={};SEED.muscles.forEach(m=>out[m.id]={direct:0,effective:0,contributors:{}});state.sessions.filter(s=>s.date>=start&&s.date<=end&&["complete","shortened"].includes(s.status)).forEach(s=>s.items.forEach(item=>{const ex=item.exerciseSnapshot||getExercise(item.exerciseId),c=workingSets(item).length;if(!c||!ex?.primaryMuscle)return;const pri=ex.primaryMuscle;if(out[pri]){out[pri].direct+=c;out[pri].effective+=c;out[pri].contributors[ex.name]=(out[pri].contributors[ex.name]||0)+c;}(ex.secondaryMuscles||[]).forEach(mid=>{if(out[mid]){const add=c*num(state.settings.secondaryMultiplier||.5);out[mid].effective+=add;out[mid].contributors[ex.name]=(out[mid].contributors[ex.name]||0)+add;}});}));return out;}
  function bodyMapSVG(side,stats){const intensity=id=>{const t=state.settings.muscleTargets[id]||[1,1],v=stats[id]?.effective||0,r=t[0]?v/t[0]:0;return r<=0?"#e8ecf2":r<.45?"#dbeafe":r<.8?"#93c5fd":r<1.2?"#3b82f6":"#1d4ed8";};const f=side==="front";return `<svg class="body-map" viewBox="0 0 180 340" role="img" aria-label="${side} muscle training map"><circle class="sil" cx="90" cy="28" r="20"/><rect class="sil" x="72" y="48" width="36" height="75" rx="18"/><path class="sil" d="M72 58 L46 72 L34 150 L48 152 L61 91 L70 82 Z"/><path class="sil" d="M108 58 L134 72 L146 150 L132 152 L119 91 L110 82 Z"/><path class="sil" d="M76 119 L63 205 L78 312 L90 312 L91 194 L88 120 Z"/><path class="sil" d="M104 119 L117 205 L102 312 L90 312 L89 194 L92 120 Z"/>
      ${f?frontMuscles(intensity):backMuscles(intensity)}<text x="90" y="332">${f?"Front":"Back"}</text></svg>`;}
  function frontMuscles(c){return `<ellipse class="muscle muscle-shape" data-muscle="chest" cx="75" cy="76" rx="14" ry="11" fill="${c("chest")}"/><ellipse class="muscle muscle-shape" data-muscle="chest" cx="105" cy="76" rx="14" ry="11" fill="${c("chest")}"/><ellipse class="muscle muscle-shape" data-muscle="front_delts" cx="58" cy="69" rx="8" ry="10" fill="${c("front_delts")}"/><ellipse class="muscle muscle-shape" data-muscle="front_delts" cx="122" cy="69" rx="8" ry="10" fill="${c("front_delts")}"/><ellipse class="muscle muscle-shape" data-muscle="side_delts" cx="51" cy="75" rx="6" ry="12" fill="${c("side_delts")}"/><ellipse class="muscle muscle-shape" data-muscle="side_delts" cx="129" cy="75" rx="6" ry="12" fill="${c("side_delts")}"/><ellipse class="muscle muscle-shape" data-muscle="biceps" cx="48" cy="105" rx="6" ry="13" fill="${c("biceps")}"/><ellipse class="muscle muscle-shape" data-muscle="biceps" cx="132" cy="105" rx="6" ry="13" fill="${c("biceps")}"/><path class="muscle muscle-shape" data-muscle="abs" d="M78 88 Q90 84 102 88 L100 121 Q90 126 80 121 Z" fill="${c("abs")}"/><path class="muscle muscle-shape" data-muscle="obliques" d="M70 88 L78 90 L80 121 L72 116 Z" fill="${c("obliques")}"/><path class="muscle muscle-shape" data-muscle="obliques" d="M110 88 L102 90 L100 121 L108 116 Z" fill="${c("obliques")}"/><path class="muscle muscle-shape" data-muscle="forearms" d="M42 120 L51 120 L48 151 L37 149 Z" fill="${c("forearms")}"/><path class="muscle muscle-shape" data-muscle="forearms" d="M138 120 L129 120 L132 151 L143 149 Z" fill="${c("forearms")}"/><path class="muscle muscle-shape" data-muscle="quads" d="M71 128 L88 128 L87 202 L68 202 Z" fill="${c("quads")}"/><path class="muscle muscle-shape" data-muscle="quads" d="M109 128 L92 128 L93 202 L112 202 Z" fill="${c("quads")}"/><path class="muscle muscle-shape" data-muscle="calves" d="M69 213 L83 213 L80 292 L70 292 Z" fill="${c("calves")}"/><path class="muscle muscle-shape" data-muscle="calves" d="M111 213 L97 213 L100 292 L110 292 Z" fill="${c("calves")}"/>`;}
  function backMuscles(c){return `<ellipse class="muscle muscle-shape" data-muscle="rear_delts" cx="58" cy="70" rx="8" ry="10" fill="${c("rear_delts")}"/><ellipse class="muscle muscle-shape" data-muscle="rear_delts" cx="122" cy="70" rx="8" ry="10" fill="${c("rear_delts")}"/><ellipse class="muscle muscle-shape" data-muscle="side_delts" cx="51" cy="76" rx="6" ry="12" fill="${c("side_delts")}"/><ellipse class="muscle muscle-shape" data-muscle="side_delts" cx="129" cy="76" rx="6" ry="12" fill="${c("side_delts")}"/><path class="muscle muscle-shape" data-muscle="traps" d="M75 54 L90 65 L105 54 L106 76 L74 76 Z" fill="${c("traps")}"/><path class="muscle muscle-shape" data-muscle="upper_back" d="M67 72 L90 78 L113 72 L108 95 L72 95 Z" fill="${c("upper_back")}"/><path class="muscle muscle-shape" data-muscle="lats" d="M69 82 L82 91 L78 122 L65 112 Z" fill="${c("lats")}"/><path class="muscle muscle-shape" data-muscle="lats" d="M111 82 L98 91 L102 122 L115 112 Z" fill="${c("lats")}"/><path class="muscle muscle-shape" data-muscle="lower_back" d="M80 99 L100 99 L103 123 L77 123 Z" fill="${c("lower_back")}"/><ellipse class="muscle muscle-shape" data-muscle="triceps" cx="48" cy="105" rx="6" ry="13" fill="${c("triceps")}"/><ellipse class="muscle muscle-shape" data-muscle="triceps" cx="132" cy="105" rx="6" ry="13" fill="${c("triceps")}"/><path class="muscle muscle-shape" data-muscle="forearms" d="M42 120 L51 120 L48 151 L37 149 Z" fill="${c("forearms")}"/><path class="muscle muscle-shape" data-muscle="forearms" d="M138 120 L129 120 L132 151 L143 149 Z" fill="${c("forearms")}"/><path class="muscle muscle-shape" data-muscle="glutes" d="M69 124 Q90 117 90 149 Q72 151 67 140 Z" fill="${c("glutes")}"/><path class="muscle muscle-shape" data-muscle="glutes" d="M111 124 Q90 117 90 149 Q108 151 113 140 Z" fill="${c("glutes")}"/><path class="muscle muscle-shape" data-muscle="hamstrings" d="M70 150 L88 150 L86 205 L68 205 Z" fill="${c("hamstrings")}"/><path class="muscle muscle-shape" data-muscle="hamstrings" d="M110 150 L92 150 L94 205 L112 205 Z" fill="${c("hamstrings")}"/><path class="muscle muscle-shape" data-muscle="calves" d="M69 213 L83 213 L80 292 L70 292 Z" fill="${c("calves")}"/><path class="muscle muscle-shape" data-muscle="calves" d="M111 213 L97 213 L100 292 L110 292 Z" fill="${c("calves")}"/>`;}
  function exerciseAnalyticsHTML(){const active=Object.values(state.exercises).filter(e=>!e.archived).sort((a,b)=>a.name.localeCompare(b.name)),ex=getExercise(selectedExerciseAnalyticsId)||active[0];if(ex)selectedExerciseAnalyticsId=ex.id;const stats=exerciseStats(ex?.id),points=exerciseE1rmPoints(ex?.id);return `<section class="card"><label>Exercise<select id="analyticsExerciseSelect">${active.map(x=>`<option value="${x.id}" ${x.id===selectedExerciseAnalyticsId?"selected":""}>${esc(x.name)}</option>`).join("")}</select></label></section>${ex?`<section class="grid-2"><div class="metric"><span class="meta">Best e1RM</span><strong>${stats.bestE?`${round1(unitWeight(stats.bestE))} ${weightUnit()}`:"—"}</strong></div><div class="metric"><span class="meta">Highest load</span><strong>${stats.bestLoad?`${unitWeight(stats.bestLoad)} ${weightUnit()}`:"—"}</strong></div><div class="metric"><span class="meta">Best session volume</span><strong>${stats.bestVolume?`${Math.round(unitWeight(stats.bestVolume))}`:"—"}</strong></div><div class="metric"><span class="meta">Last performed</span><strong style="font-size:18px">${stats.lastDate?fmtDate(stats.lastDate):"—"}</strong></div></section><section class="card"><div class="section-title"><h2>Estimated 1RM trend</h2><span class="meta">${esc(ex.name)}</span></div><div class="chart">${lineChart(points.map(p=>({date:p.date,value:unitWeight(p.value)})),weightUnit())}</div></section><section class="card"><h2>Top-load trend</h2><div class="chart">${lineChart(exercisePerformanceSeries(ex.id,"load").map(p=>({date:p.date,value:unitWeight(p.value)})),weightUnit())}</div></section><section class="card"><h2>Session-volume trend</h2><div class="chart">${lineChart(exercisePerformanceSeries(ex.id,"volume").map(p=>({date:p.date,value:unitWeight(p.value)})),`${weightUnit()}-reps`)}</div></section><section class="card"><h2>Exercise history</h2><div class="list">${exerciseHistoryRows(ex.id)}</div></section>`:""}`;}
  function exercisePerformanceSeries(exId,kind){return state.sessions.filter(s=>["complete","shortened"].includes(s.status)&&s.items.some(i=>i.exerciseId===exId)).sort((a,b)=>a.date.localeCompare(b.date)).map(s=>{const sets=s.items.filter(i=>i.exerciseId===exId).flatMap(i=>workingSets(i));let value=0;if(kind==="load")value=Math.max(0,...sets.map(x=>x.loadKg||0));else if(kind==="volume")value=sets.reduce((a,x)=>a+setVolume(x),0);else value=sets.reduce((a,x)=>a+(x.reps||0),0);return value?{date:s.date,value}:null;}).filter(Boolean);}
  function exerciseStats(exId){const sessions=state.sessions.filter(s=>["complete","shortened"].includes(s.status)&&s.items.some(i=>i.exerciseId===exId));let bestE=0,bestLoad=0,bestVolume=0,lastDate=null;sessions.forEach(s=>{const items=s.items.filter(i=>i.exerciseId===exId);const volume=items.reduce((a,i)=>a+workingSets(i).reduce((x,st)=>x+setVolume(st),0),0);bestVolume=Math.max(bestVolume,volume);items.flatMap(i=>workingSets(i)).forEach(st=>{bestLoad=Math.max(bestLoad,st.loadKg||0);bestE=Math.max(bestE,e1rm(st.loadKg,st.reps));});if(!lastDate||s.date>lastDate)lastDate=s.date;});return {bestE,bestLoad,bestVolume,lastDate};}
  function exerciseE1rmPoints(exId){return state.sessions.filter(s=>["complete","shortened"].includes(s.status)&&s.items.some(i=>i.exerciseId===exId)).sort((a,b)=>a.date.localeCompare(b.date)).map(s=>{const sets=s.items.filter(i=>i.exerciseId===exId).flatMap(i=>workingSets(i));const best=Math.max(0,...sets.map(st=>e1rm(st.loadKg,st.reps)));return best?{date:s.date,value:best}:null;}).filter(Boolean);}
  function exerciseHistoryRows(exId){const ex=getExercise(exId);const arr=state.sessions.filter(s=>s.items.some(i=>i.exerciseId===exId)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,30);return arr.map(s=>{const sets=s.items.filter(i=>i.exerciseId===exId).flatMap(i=>workingSets(i));return `<div class="list-row"><div><strong>${fmtDate(s.date)}</strong><div class="meta">${sets.map(st=>setSummary(st,ex)).join(" · ")||"No completed working sets"}</div></div><span class="pill neutral">${sets.length} sets</span></div>`;}).join("")||`<div class="empty">No history for this exercise.</div>`;}
  function lineChart(points,unit){if(points.length<2)return `<div class="chart-empty">Log at least two data points to see a trend.</div>`;const w=640,h=170,p=22,vals=points.map(x=>x.value),min=Math.min(...vals),max=Math.max(...vals),range=Math.max(.1,max-min);const xy=points.map((pt,i)=>({x:p+i*(w-2*p)/(points.length-1),y:h-p-(pt.value-min)/range*(h-2*p)}));const path=xy.map((q,i)=>`${i?"L":"M"}${q.x.toFixed(1)},${q.y.toFixed(1)}`).join(" ");return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Trend chart"><path d="${path}" fill="none" stroke="#2563eb" stroke-width="3"/>${xy.map(q=>`<circle cx="${q.x}" cy="${q.y}" r="4" fill="#2563eb"/>`).join("")}<text x="${p}" y="14" font-size="11" fill="#667085">${round1(max)} ${unit}</text><text x="${p}" y="${h-4}" font-size="11" fill="#667085">${round1(min)} ${unit}</text></svg>`;}

  function bodyHTML(){const entries=[...state.bodyEntries].sort((a,b)=>a.date.localeCompare(b.date));const weightPts=entries.filter(x=>num(x.weight)>0).map(x=>({date:x.date,value:x.weight}));const waistPts=entries.filter(x=>num(x.waist)>0).map(x=>({date:x.date,value:x.waist}));const latest=entries[entries.length-1]||{};return `<section class="card"><div class="row"><div><p class="eyebrow">Body measurements</p><h2>Track trends, not daily noise</h2></div><button class="btn primary" id="addBodyEntryBtn" type="button">+ Entry</button></div></section><section class="grid-2"><div class="metric"><span class="meta">7-day weight average</span><strong>${bodyAverage("weight",7)?`${round1(bodyAverage("weight",7))} kg`:"—"}</strong></div><div class="metric"><span class="meta">Latest waist</span><strong>${latestBody("waist")?`${round1(latestBody("waist").waist)} cm`:"—"}</strong></div></section><section class="card"><h2>Body-weight trend</h2><div class="chart">${lineChart(weightPts.slice(-30),"kg")}</div></section><section class="card"><h2>Waist trend</h2><div class="chart">${lineChart(waistPts.slice(-30),"cm")}</div></section><section class="card"><h2>Measurement history</h2><div class="list">${entries.slice().reverse().slice(0,30).map(e=>`<div class="list-row click-row body-entry-row" data-body="${e.id}"><div><strong>${fmtDate(e.date)}</strong><div class="meta">${bodyFields.filter(([k])=>e[k]!=null).map(([k,n,u])=>`${n}: ${e[k]} ${u}`).join(" · ")}</div></div><span>›</span></div>`).join("")||`<div class="empty">No measurements yet.</div>`}</div></section>`;}
  function latestBody(field){return [...state.bodyEntries].filter(x=>num(x[field])>0).sort((a,b)=>b.date.localeCompare(a.date))[0]||null;}
  function bodyAverage(field,days){const start=addDays(isoToday(),-(days-1));const vals=state.bodyEntries.filter(x=>x.date>=start&&x.date<=isoToday()&&num(x[field])>0).map(x=>num(x[field]));return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;}
  function openBodyEntryModal(date=isoToday(),focus=null,entry=null){const e=entry||state.bodyEntries.find(x=>x.date===date)||{id:uid("body"),date};const fields=state.settings.visibleBodyFields||["weight","waist"];openModal(entry?"Edit body entry":"Body measurement",fmtDate(date),`<label>Date<input id="bodyDate" type="date" value="${e.date}"></label><div class="form-grid">${bodyFields.filter(([k])=>fields.includes(k)||["weight","waist"].includes(k)).map(([k,n,u])=>`<label>${n} (${u})<input id="body_${k}" type="number" step="0.1" min="0" value="${e[k]??""}"></label>`).join("")}</div>${entry?`<button class="btn danger" id="deleteBodyEntry" type="button">Delete entry</button>`:""}`,`<button class="btn primary" id="saveBodyEntry" type="button">Save</button>`);setTimeout(()=>focus&&byId(`body_${focus}`)?.focus(),0);byId("saveBodyEntry").addEventListener("click",()=>{e.date=byId("bodyDate").value||date;bodyFields.forEach(([k])=>{const el=byId(`body_${k}`);if(el){const v=Number(el.value);if(Number.isFinite(v)&&v>0)e[k]=v;else delete e[k];}});if(!entry&&!state.bodyEntries.includes(e))state.bodyEntries.push(e);save();closeModal();if(activeView==="progress")renderProgress();else render();showToast("Measurement saved.");});byId("deleteBodyEntry")?.addEventListener("click",()=>{state.bodyEntries=state.bodyEntries.filter(x=>x.id!==e.id);save();closeModal();renderProgress();});}

  function goalsHTML(){return `<section class="card"><div class="row"><div><p class="eyebrow">Goals</p><h2>Measurable targets</h2></div><button class="btn primary" id="addGoalBtn" type="button">+ Goal</button></div><div class="list" style="margin-top:8px">${state.goals.map(goalRow).join("")||`<div class="empty">No goals yet.</div>`}</div></section>`;}
  function goalRow(g){const prog=goalProgress(g),pct=prog.target?Math.max(0,Math.min(100,prog.current/prog.target*100)):0;return `<div class="list-row click-row goal-row" data-goal="${g.id}"><div><strong>${esc(g.name)}</strong><div class="meta">Current ${prog.currentDisplay} · Target ${prog.targetDisplay}</div><div class="bar"><span style="width:${pct}%"></span></div></div><span class="pill ${pct>=100?"good":"neutral"}">${Math.round(pct)}%</span></div>`;}
  function goalProgress(g){if(g.type==="exercise_e1rm"){const best=exerciseStats(g.exerciseId).bestE,target=num(g.targetKg);return {current:best,target,currentDisplay:best?`${round1(unitWeight(best))} ${weightUnit()}`:"—",targetDisplay:`${round1(unitWeight(target))} ${weightUnit()}`};}if(g.type==="exercise_load"){const best=exerciseStats(g.exerciseId).bestLoad,target=num(g.targetKg);return {current:best,target,currentDisplay:best?`${unitWeight(best)} ${weightUnit()}`:"—",targetDisplay:`${unitWeight(target)} ${weightUnit()}`};}if(g.type==="weekly_workouts"){const w=weekSummary(isoToday()),cur=w.completed+w.shortened,target=num(g.target);return {current:cur,target,currentDisplay:`${cur} workouts`,targetDisplay:`${target}/week`};}if(g.type==="waist"){const cur=latestBody("waist")?.waist||0,target=num(g.target);return {current:target?Math.min(target,Math.max(0,target-(cur-target))):0,target,currentDisplay:cur?`${cur} cm`:"—",targetDisplay:`≤${target} cm`};}const cur=latestBody("weight")?.weight||0,target=num(g.target);return {current:cur,target,currentDisplay:cur?`${cur} kg`:"—",targetDisplay:`${target} kg`};}
  function openGoalModal(g=null){const active=Object.values(state.exercises).filter(e=>!e.archived).sort((a,b)=>a.name.localeCompare(b.name));const v=g||{type:"exercise_e1rm",exerciseId:"bench",targetKg:100,name:"Bench e1RM 100 kg"};openModal(g?"Edit goal":"New goal","Set a measurable target",`<div class="stack"><label>Goal type<select id="goalType"><option value="exercise_e1rm" ${v.type==="exercise_e1rm"?"selected":""}>Exercise estimated 1RM</option><option value="exercise_load" ${v.type==="exercise_load"?"selected":""}>Exercise load</option><option value="weight" ${v.type==="weight"?"selected":""}>Body weight</option><option value="waist" ${v.type==="waist"?"selected":""}>Waist maximum</option><option value="weekly_workouts" ${v.type==="weekly_workouts"?"selected":""}>Workout consistency / week</option></select></label><label>Exercise<select id="goalExercise">${active.map(e=>`<option value="${e.id}" ${v.exerciseId===e.id?"selected":""}>${esc(e.name)}</option>`).join("")}</select></label><label>Target<input id="goalTarget" type="number" step="0.1" value="${v.targetKg?unitWeight(v.targetKg):(v.target||"")}"></label><label>Goal name<input id="goalName" value="${esc(v.name||"")}"></label>${g?`<button class="btn danger" id="deleteGoalBtn" type="button">Delete goal</button>`:""}</div>`,`<button class="btn primary" id="saveGoalBtn" type="button">Save</button>`);byId("saveGoalBtn").addEventListener("click",()=>{const type=byId("goalType").value,obj=g||{id:uid("goal")};obj.type=type;obj.exerciseId=byId("goalExercise").value;obj.name=byId("goalName").value.trim()||"Goal";if(type.startsWith("exercise_"))obj.targetKg=toKg(byId("goalTarget").value);else obj.target=num(byId("goalTarget").value);if(!g)state.goals.push(obj);save();closeModal();renderProgress();});byId("deleteGoalBtn")?.addEventListener("click",()=>{state.goals=state.goals.filter(x=>x.id!==g.id);save();closeModal();renderProgress();});}

  function wireProgressTab(){if(progressTab==="muscles"){document.querySelectorAll(".muscle-shape,.muscle-detail").forEach(x=>x.addEventListener("click",()=>openMuscleDetail(x.dataset.muscle)));}if(progressTab==="exercise")byId("analyticsExerciseSelect")?.addEventListener("change",e=>{selectedExerciseAnalyticsId=e.target.value;renderProgress();});if(progressTab==="body"){byId("addBodyEntryBtn")?.addEventListener("click",()=>openBodyEntryModal());document.querySelectorAll(".body-entry-row").forEach(r=>r.addEventListener("click",()=>openBodyEntryModal(null,null,state.bodyEntries.find(x=>x.id===r.dataset.body))));}if(progressTab==="goals"){byId("addGoalBtn")?.addEventListener("click",()=>openGoalModal());document.querySelectorAll(".goal-row").forEach(r=>r.addEventListener("click",()=>openGoalModal(state.goals.find(x=>x.id===r.dataset.goal))));}}
  function openMuscleDetail(mid){const start=startOfWeek(isoToday()),stats=muscleStatsForRange(start,addDays(start,6))[mid]||{direct:0,effective:0,contributors:{}},last=muscleStatsForRange(addDays(start,-7),addDays(start,-1))[mid]||{direct:0,effective:0},t=state.settings.muscleTargets[mid]||[0,0];const fourWeeks=[0,1,2,3].map(k=>muscleStatsForRange(addDays(start,-7*k),addDays(start,6-7*k))[mid]?.effective||0);const avg4=fourWeeks.reduce((a,b)=>a+b,0)/4;const contrib=Object.entries(stats.contributors).sort((a,b)=>b[1]-a[1]);openModal("Muscle detail",muscleName(mid),`<div class="grid-3"><div class="metric"><span class="meta">Direct</span><strong>${round1(stats.direct)}</strong></div><div class="metric"><span class="meta">Effective</span><strong>${round1(stats.effective)}</strong></div><div class="metric"><span class="meta">Target</span><strong>${t[0]}–${t[1]}</strong></div></div><div class="note-box">Last week: ${round1(last.effective)} effective sets · 4-week average: ${round1(avg4)}</div><div class="list">${contrib.map(([n,v])=>`<div class="list-row"><strong>${esc(n)}</strong><span class="pill">${round1(v)} sets</span></div>`).join("")||`<div class="empty">No contributors this week.</div>`}</div>`,"");}

  // ---------- MORE / SETTINGS / DATA HEALTH ----------
  function renderMore(){const issues=dataHealthIssues();view.innerHTML=`<div class="stack"><section class="card"><div class="section-title"><h2>Exercise Library</h2><button class="btn primary small-btn" id="moreAddExercise" type="button">+ Exercise</button></div><p class="meta">Create, edit, archive, and map exercises to muscles.</p><button class="btn ghost" id="moreOpenLibrary" type="button">Open library</button></section><section class="card"><h2>Utilities</h2><div class="grid-2" style="margin-top:10px"><button class="btn ghost" id="plateCalcBtn" type="button">Plate calculator</button><button class="btn ghost" id="warmupCalcBtn" type="button">Warm-up calculator</button></div></section><section class="card"><div class="section-title"><h2>Data Health</h2><span class="pill ${issues.length?"warn":"good"}">${issues.length?`${issues.length} issue${issues.length>1?"s":""}`:"Healthy"}</span></div>${issues.length?`<div class="stack" style="margin-top:10px">${issues.slice(0,12).map(x=>`<div class="health-issue"><strong>${esc(x.title)}</strong><br>${esc(x.text)}</div>`).join("")}</div>`:`<div class="health-ok" style="margin-top:10px">No structural data problems detected.</div>`}</section><section class="card"><h2>Preferences</h2><div class="form-grid" style="margin-top:10px"><label>Units<select id="unitsSetting"><option value="kg" ${state.settings.units==="kg"?"selected":""}>kg</option><option value="lb" ${state.settings.units==="lb"?"selected":""}>lb</option></select></label><label>Week starts<select id="weekSetting"><option value="monday" ${state.settings.weekStarts==="monday"?"selected":""}>Monday</option><option value="sunday" ${state.settings.weekStarts==="sunday"?"selected":""}>Sunday</option></select></label></div><div class="checks" style="margin-top:10px"><label class="check-chip"><input id="rirSetting" type="checkbox" ${state.settings.trackRir?"checked":""}><span>Track RIR</span></label><label class="check-chip"><input id="restSetting" type="checkbox" ${state.settings.autoRest?"checked":""}><span>Auto rest timer</span></label></div><button class="btn primary" id="savePrefsBtn" type="button" style="margin-top:10px">Save preferences</button></section><section class="card"><h2>Muscle targets</h2><p class="meta">Weekly effective-set target ranges used by the muscle map and insights.</p><button class="btn ghost" id="editTargetsBtn" type="button">Edit targets</button></section><section class="card"><h2>Body measurement fields</h2><p class="meta">Choose which measurements appear in the Body entry form.</p><button class="btn ghost" id="editBodyFieldsBtn" type="button">Configure fields</button></section><section class="card"><h2>Backup & restore</h2><p class="meta">All data remains local to this browser unless you export it.</p><div class="wrap"><button class="btn ghost" id="exportBtn" type="button">Export JSON</button><label class="btn ghost">Import JSON<input class="hidden" id="importInput" type="file" accept="application/json,.json"></label>${localStorage.getItem(MIGRATION_BACKUP_KEY)?`<button class="btn ghost" id="legacyBackupBtn" type="button">Download V1 migration backup</button>`:""}</div></section><section class="card"><h2>Advanced</h2><button class="btn danger" id="resetBtn" type="button">Reset Strength OS data</button></section></div>`;
    byId("moreAddExercise").addEventListener("click",()=>openExerciseModal(null));byId("moreOpenLibrary").addEventListener("click",openLibraryModal);byId("plateCalcBtn").addEventListener("click",openPlateCalculator);byId("warmupCalcBtn").addEventListener("click",openWarmupCalculator);byId("savePrefsBtn").addEventListener("click",()=>{state.settings.units=byId("unitsSetting").value;state.settings.weekStarts=byId("weekSetting").value;state.settings.trackRir=byId("rirSetting").checked;state.settings.autoRest=byId("restSetting").checked;save();renderMore();showToast("Preferences saved.");});byId("editTargetsBtn").addEventListener("click",openMuscleTargetsModal);byId("editBodyFieldsBtn").addEventListener("click",openBodyFieldsModal);byId("exportBtn").addEventListener("click",()=>downloadText(`strength-os-backup-${isoToday()}.json`,JSON.stringify(state,null,2),"application/json"));byId("importInput").addEventListener("change",importBackup);byId("legacyBackupBtn")?.addEventListener("click",()=>downloadText("strength-os-v1-migration-backup.json",localStorage.getItem(MIGRATION_BACKUP_KEY),"application/json"));byId("resetBtn").addEventListener("click",()=>{if(!confirm("Reset all Strength OS data on this device? Export a backup first."))return;state=newState();save();selectedProgramId=state.settings.activeProgramId;navigate("train");});
  }
  function dataHealthIssues(){const issues=[];const ids=new Set();state.sessions.forEach(s=>{if(ids.has(s.id))issues.push({title:"Duplicate session ID",text:`Session ${s.id} is duplicated.`});ids.add(s.id);if(s.startTime&&s.endTime&&s.endTime<s.startTime)issues.push({title:"Invalid session duration",text:`${s.name} on ${s.date} ends before it starts.`});s.items.forEach(i=>{if(!state.exercises[i.exerciseId]&&!i.exerciseSnapshot)issues.push({title:"Missing exercise reference",text:`A workout on ${s.date} references ${i.exerciseId}.`});i.sets.forEach(st=>{if(st.rir!=null&&(st.rir<0||st.rir>5))issues.push({title:"Invalid RIR",text:`${s.date} contains RIR ${st.rir}.`});if(st.loadKg>1000)issues.push({title:"Unusually high load",text:`${s.date} contains ${round1(st.loadKg)} kg. Verify this entry.`});if(st.complete&&st.type!=="warmup"&&!st.reps&&!st.durationSec&&!st.distanceKm)issues.push({title:"Empty completed set",text:`${s.date} contains a completed set without reps/duration/distance.`});});});});Object.values(state.exercises).forEach(e=>{if(!e.primaryMuscle)issues.push({title:"Exercise missing primary muscle",text:e.name});});Object.values(state.programs).forEach(p=>p.days.forEach(d=>d.items.forEach(i=>{if(!state.exercises[i.exerciseId])issues.push({title:"Program references missing exercise",text:`${p.name} → ${d.name} → ${i.exerciseId}`});})));return issues;}
  function openMuscleTargetsModal(){openModal("Muscle targets","Weekly effective sets",`<div class="form-grid">${SEED.muscles.map(m=>{const t=state.settings.muscleTargets[m.id]||[0,0];return `<div class="form-grid"><label>${m.name} min<input id="target_${m.id}_min" type="number" min="0" max="40" value="${t[0]}"></label><label>${m.name} max<input id="target_${m.id}_max" type="number" min="0" max="50" value="${t[1]}"></label></div>`;}).join("")}</div>`,`<button class="btn primary" id="saveTargetsBtn" type="button">Save targets</button>`);byId("saveTargetsBtn").addEventListener("click",()=>{SEED.muscles.forEach(m=>{const mn=clamp(byId(`target_${m.id}_min`).value,0,40)||0,mx=clamp(byId(`target_${m.id}_max`).value,0,50)||mn;state.settings.muscleTargets[m.id]=[mn,Math.max(mn,mx)];});save();closeModal();renderMore();});}
  function openBodyFieldsModal(){openModal("Body fields","Choose measurements",`<div class="checks">${bodyFields.map(([k,n])=>`<label class="check-chip"><input class="body-field-check" type="checkbox" value="${k}" ${(state.settings.visibleBodyFields||[]).includes(k)||["weight","waist"].includes(k)?"checked":""} ${["weight","waist"].includes(k)?"disabled":""}><span>${n}</span></label>`).join("")}</div>`,`<button class="btn primary" id="saveBodyFieldsBtn" type="button">Save</button>`);byId("saveBodyFieldsBtn").addEventListener("click",()=>{state.settings.visibleBodyFields=["weight","waist",...[...document.querySelectorAll(".body-field-check:checked")].map(x=>x.value).filter(x=>!["weight","waist"].includes(x))];save();closeModal();renderMore();});}
  function openPlateCalculator(){const inv=state.settings.plateInventory||[20,15,10,5,2.5,1.25];openModal("Plate calculator","Barbell loading",`<div class="form-grid"><label>Target (${weightUnit()})<input id="plateTarget" type="number" step="0.5" value="82.5"></label><label>Bar (${weightUnit()})<input id="plateBar" type="number" step="0.5" value="${state.settings.barWeight||20}"></label></div><label>Available plates per side<input id="plateInventory" value="${inv.join(", ")}"></label><button class="btn secondary" id="calcPlatesBtn" type="button">Calculate</button><div id="plateResult" class="note-box">Enter your target load.</div>`,"");byId("calcPlatesBtn").addEventListener("click",()=>{const target=num(byId("plateTarget").value),bar=num(byId("plateBar").value),plates=byId("plateInventory").value.split(",").map(x=>num(x.trim())).filter(x=>x>0).sort((a,b)=>b-a);state.settings.plateInventory=plates;state.settings.barWeight=bar;save();let per=(target-bar)/2;if(per<0)return byId("plateResult").textContent="Target is lighter than the bar.";const used=[];plates.forEach(p=>{while(per+1e-9>=p){used.push(p);per-=p;}});byId("plateResult").innerHTML=per<.01?`Per side: <strong>${used.length?used.join(" + "):"no plates"}</strong>`:`Closest loadable combination leaves ${round1(per)} ${weightUnit()} per side.`;});}
  function openWarmupCalculator(){openModal("Warm-up calculator","Simple ramp to working weight",`<div class="form-grid"><label>Working load (${weightUnit()})<input id="warmLoad" type="number" step="0.5" value="80"></label><label>Bar / minimum load<input id="warmBar" type="number" step="0.5" value="20"></label></div><button class="btn secondary" id="calcWarmBtn" type="button">Generate</button><div id="warmResult" class="note-box">Uses low-fatigue ramp sets.</div>`,"");byId("calcWarmBtn").addEventListener("click",()=>{const load=num(byId("warmLoad").value),bar=num(byId("warmBar").value);if(load<=0)return;const rounds=[[Math.max(bar,load*.45),8],[Math.max(bar,load*.65),5],[Math.max(bar,load*.8),3],[Math.max(bar,load*.9),1]].filter((x,i,a)=>x[0]<load&&(!i||Math.abs(x[0]-a[i-1][0])>2));byId("warmResult").innerHTML=rounds.map(([w,r])=>`${roundToIncrement(w,2.5)} ${weightUnit()} × ${r}`).join("<br>")+`<br><strong>${load} ${weightUnit()} → working sets</strong>`;});}
  function roundToIncrement(v,inc){return Math.round(v/inc)*inc;}
  function downloadText(name,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500);}
  function importBackup(e){const file=e.target.files?.[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const parsed=JSON.parse(r.result);if(!parsed||typeof parsed!=="object")throw Error();state=(parsed.workouts||parsed.body||parsed.nutrition)?migrateLegacy(parsed):normalizeState(parsed);save();selectedProgramId=state.settings.activeProgramId;showToast(parsed.workouts||parsed.body?"Legacy backup migrated and imported.":"Backup imported.");renderMore();}catch{showToast("Invalid Strength OS backup.");}};r.readAsText(file);e.target.value="";}

  // ---------- MODAL HELPERS ----------
  function openModal(eyebrow,title,body,actions=""){byId("modalEyebrow").textContent=eyebrow||"";byId("modalTitle").textContent=title||"";modalBody.innerHTML=body||"";modalActions.innerHTML=actions||"";if(!modal.open)modal.showModal();}
  function closeModal(){if(modal.open)modal.close();}
  function openTextModal(title,value,onSave){openModal("Note",title,`<label>Text<textarea id="textModalValue">${esc(value)}</textarea></label>`,`<button class="btn primary" id="textModalSave" type="button">Save</button>`);byId("textModalSave").addEventListener("click",()=>{onSave(byId("textModalValue").value.trim());closeModal();});}

})();
